INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1,'Вудлище Yamaga Blanks Blue Current TZ BLC-70/Tz NANO','FSH0000992','Вудлище Yamaga Blanks Blue Current 70Tz Nano - універсальний лайт нового покоління, виготовлений з карбонового композиту з особливою молекулярною структурою волокон і гранично низьким вмістом смол. Недосяжне раніше співвідношення легкості та жорсткості тонкостінного бланка дає йому ідеальну чутливість, забезпечує можливість поєднати відмінні кастингові властивості по всій ширині тестового діапазону зі здатністю залишатися жорстким і зібраним у будь-якій анімації, включаючи ривкові техніки з приманками джигів або воблерами-мінноу. Змінюючи товщину РЕ-шнурів, що застосовуються, можна адаптувати цей унікальний інструмент до будь-якої лайтової техніки. З ниткою PE #0.4 це елітний джиговик під навантаження до 8 грамів, для полювання на будь-якого хижака, від ніжногубого окуня до судаків та щук з їх потужними щелепами. Встановіть на свою котушку шпулю з РЕ #0.6 або навіть #0.8 - і у вас в руках радикальний твічінговий інструмент, який впевнено оперує воблерами-мінноу довжиною до 8 см. У будь-якому випадку якість лову з цим найлегшим, надінформативним і потужним вудлищем вас вразить: нічого подібного ви навіть уявити не могли. Довжина моделі BLC-70Tz Nano: 2.19 м. Маса: 64 гр. Строй: fast.Tubular tip.Вміст карбону: 99,6%. Кільця: Fuji KR-series Ti. Тест з приманок: 0.7 - 7 гр. Тест із шнура: PE#0.2-0.4. Made in Japan.','https://fishingstock.ua/upload/iblock/bdf/bdf2d42f04072e8b58c32a4783918cf2.jpeg, https://fishingstock.ua/upload/iblock/319/319d119110e52faa7df4ad9f2c60e6d4.jpeg, https://fishingstock.ua/upload/iblock/0c6/0c653f2f7489b76b908370e7dd9fc950.jpeg, https://fishingstock.ua/upload/iblock/03a/03aa046dfe1d70914c0102b6376df493.jpeg','шт.',20960.0,1,206,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2,'Вудлище Yamaga Blanks Blue Current TZ BLC-70/Tz NANO','','Вудлище Yamaga Blanks Blue Current 70Tz Nano - універсальний лайт нового покоління, виготовлений з карбонового композиту з особливою молекулярною структурою волокон і гранично низьким вмістом смол. Недосяжне раніше співвідношення легкості та жорсткості тонкостінного бланка дає йому ідеальну чутливість, забезпечує можливість поєднати відмінні кастингові властивості по всій ширині тестового діапазону зі здатністю залишатися жорстким і зібраним у будь-якій анімації, включаючи ривкові техніки з приманками джигів або воблерами-мінноу.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3,'Гачок Vanfook для блешень одинарний SP-31BL','','Ефективність роботи будь-якої приманки, оснащеної гачком Vanfook, є абсолютною. Патентований склад сталі, з якої виготовлені ці шедеври рибальського мистецтва, забезпечує неймовірну жорсткість та пружність при мінімальній товщині та масі гачка – отже, приманці забезпечена максимально легка та природна гра. Особлива форма жала і хімічна технологія його заточування дають ідеальну зацепистість, і доводять реалізацію клювань до абсолютного значення – а оскільки загартовуються ці крихітні вбивці за стародавніми японськими традиціями термообробки збройової сталі, затупити такий гачок практично неможливо. Застосовуйте гачки Vanfook у найвідповідальніших випадках спортивних змагань та рибальських експедицій – а якщо ви потребуєте стовідсоткової реалізації клювань на кожній рибалці, застосовуйте їх завжди!','https://fishingstock.ua/upload/iblock/907/907513fb5d777a28bcc51d6825aad2d6.jpeg','шт.',145.0,5,196,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
