INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (34,'Приманка Bait Breath Virtual Craw 3,6'''' (8шт.)','','Virtual Craw 3,6" - класичний рак, розроблений для морського лову, з надзвичайно фактурним тілом і великою кількістю активних елементів - клешнів, лапок, вусиків. Ця досить реалістична імітація раку-самітника, що покинув свою раковину, стала популярною і в прісних водах, як дуже яскрава і ефективна джигова приманка, вона успішно застосовується при лові великого окуня, судака, щуки. Особливо жадібно її їдять представники сімейства окуневих, відомі своєю особливою пристрастю до смачного силікону Bait Breath із дивовижним атрактантом BYS Mix Flavour.','https://fishingstock.ua/upload/iblock/a87/a87cce4631e551278cef588191de75b1.jpeg, https://fishingstock.ua/upload/iblock/d52/d5276371726471b532129ec937fb4fac.jpeg, https://fishingstock.ua/upload/iblock/9a2/9a2075acbb52b817135f90a4cbf9648e.jpeg','шт.',211.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (35,'Приманка Bait Breath Virtual Craw 2,6'''' (9шт.)','','Virtual Craw 2,6" - класичний рак, розроблений для морського лову, з надзвичайно фактурним тілом і великою кількістю активних елементів - клешнів, лапок, вусиків. Ця досить реалістична імітація раку-самітника, що покинув свою раковину, стала популярною і в прісних водах, як дуже яскрава і ефективна джигова приманка, вона успішно застосовується при лові великого окуня, судака, щуки. Особливо жадібно її їдять представники сімейства окуневих, відомі своєю особливою пристрастю до смачного силікону Bait Breath із дивовижним атрактантом BYS Mix Flavour.','https://fishingstock.ua/upload/iblock/a30/a30dd75fc495eac818f6dbdfee440565.jpeg, https://fishingstock.ua/upload/iblock/b6d/b6dbe482eda691e00e70f43dcbeb406f.jpeg','шт.',211.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (36,'Приманка Bait Breath Saltwater Mosya 2" (10 шт.)','','Bait Breath "Mosya" - не просте силіконове "ракоподібне". Ця дуже специфічна приманка, розроблена для морського прибережного джигового лову, стала у нас одним із суперхітів легкого джига. Її головна особливість - максимальна схильність до зависають, "парячих" проводок на мінімальному завантаженні. Значна парусність та максимальна об`ємність Mosya дозволяє вести її невеликими підкидами дуже повільно, практично не торкаючись дна. Вона чудово працює як на стоячій воді, так і на слабкій течії, контрольований знесення цього рачка на шарнірному завантаженні буває дуже ефективний при річковій лові судака і великого окуня. Легке ворушіння вусиків, оснащених масивним "п`ятачком" додатково мотивує хижака до клювання, а чудові "сідние" якості силікону Bait Breath змушують його смакувати приманку, забуваючи про все... Основна відмінність версії Saltwater від нашої улюбленої прісноводної Mosya – різноманітніші забарвлення, що включають безліч яскравих версій.','https://fishingstock.ua/upload/iblock/c7c/c7c7367d5868a90e366b2e133b755f6c.jpeg, https://fishingstock.ua/upload/iblock/eb2/eb20cb807f4610139f5eb365eb59ef8f.jpeg','шт.',212.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (37,'Воблер Megabite Popsy Max 80 F (80 мм, 18,4 гр)','','Великий і важкий Popsy Max 80 F - спеціальна приманка щука, що гарантує трофей при літній рибалці на великих мілководдях. Летить чудово, керується дуже легко, чітко реагуючи на ривки та закликаючи риб гучним бульканням. Атака щуки на Popsy Max видовищна і захоплююча - в жодному разі не поспішайте з підсіканням, обов`язково дочекайтеся відчуття удару, інакше ризикуєте висмикнути поппер прямо з широко розкритої пащі хижачки. Popsy Max 80 F оснащений дуже якісною та надійною фурнітурою. Рекомендуємо застосовувати на твердому повідку довжиною не менше 20 см.','https://fishingstock.ua/upload/iblock/dcf/dcf87c9739e0cd09cc699858aa236fd1.jpeg, https://fishingstock.ua/upload/iblock/453/45337a003b6a670339cf5101caca8562.jpeg','шт.',292.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
