INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (190,'Приманка Bait Breath Saltwater Mosya 1,5" (14 шт.) (S848 Purple-PG)','FS0010995','Bait Breath "Mosya" - не просте силіконове "ракоподібне". Ця дуже специфічна приманка, розроблена для морського прибережного джигового лову, стала у нас одним із суперхітів легкого джига. Її головна особливість - максимальна схильність до зависають, "парячих" проводок на мінімальному завантаженні. Значна парусність та максимальна об''ємність Mosya дозволяє вести її невеликими підкидами дуже повільно, практично не торкаючись дна. Вона чудово працює як на стоячій воді, так і на слабкій течії, контрольований знесення цього рачка на шарнірному завантаженні буває дуже ефективний при річковій лові судака і великого окуня. Легке ворушіння вусиків, оснащених масивним "п''ятачком" додатково мотивує хижака до клювання, а чудові "сідние" якості силікону Bait Breath змушують його смакувати приманку, забуваючи про все...
