INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (276,'Приманка Bait Breath BeTanCo Shad Tail Slim 3" (8 шт.) (S801 Red?Seed)','FS0010751','BeTanCo Shad Tail Slim – ще активніше свого прототипу BeTanCo Shad Tail. Ця приманка працює, на відміну від інших подібних бичків, усім своїм гнучким тілом. Заводячись від коливань хвостового п''ятачка, Slim звивається і корчиться, генеруючи дуже реалістичні і помітні на великій відстані коливання середовища. Її є сенс застосовувати в ситуаціях, коли придонний хижак досить активний, але його концентрація у водоймі залишає бажати кращого. Голодний судак сміливо вистачає приманку при падінні після підриву або тисне її підборіддям на протяжках по дну. Щука виходить із пасивного стану за перших ознак наближення Shad Tail Slim, не пропустить її і великий окунь.','https://fishingstock.ua/upload/iblock/d93/d93617b21284d1e581cc8942c1c77268.jpg','шт.',229.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
