INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (292,'Приманка Bait Breath BeTanCo Curly Tail 3" (6 шт.) (S833 Smoke/Silver)','FS0010897','Ця оригінальна приманка буває незамінною у прісноводних водоймах, населених бичком. Не секрет, що бички є делікатесом для всіх хижих риб – вони малорухливі, позбавлені гострих колючок, міцно прив''язані до донного ґрунту. У ситуації джигового лову пасивного, малорухливого хижака - імітація бичка може стати головним козирем спінінгіста. А якщо цей штучний бичок ще й такий ароматний, такий смачний, як Bait Breath BeTanCo Curly Tail – ваші шанси на успішну рибалку стають майже стовідсотковими. Анімація - елементарна і нехитра, це рівномірне волочіння по дну, або короткі протяжки без відриву від грунту, з довгими паузами. Клювання найчастіше виявляється у потужному нависанні на джигу - хижак думає, що спіймав смачного бичка, але рибалок точно знає: зубастий сам попався!','https://fishingstock.ua/upload/iblock/2cc/2cc1ddab0d9d6bd80c18146fbf67dda8.jpg','шт.',229.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
