INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (318,'Шнур плетеный YGK G-Soul X-3 150m (0.25 (4lb / 1.81kg))','FS00000026','Чудові робочі якості цієї яскраво-зеленої плетінки за надзвичайно дружньої її ціни зробили Х3 суперхітом продажів. Найбільш тонкі моделі дуже затребувані спортсменами і любителями ВУЛ-полювання – насправді інших настільки ж бюджетних, але при цьому міцних і летких тонких ниток, як Х3 #0.25/4lb і #0.3/4,5lb на ринку просто не існує. Ще одна дуже зручна особливість лінійки Х3 – наявність усіх, навіть рідкісних діаметрів шнура. У ній є не тільки звичні #0.6/9lb, #0.8/13lb та #1.0/16lb – а й унікальні #0.5/7,5lb, #0.7/11,5lb. Made in Japan.','https://fishingstock.ua/upload/iblock/6c9/6c99db550cec1cc7ff825c2f8a177a31.jpeg','шт.',1228.0,3,209,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
