INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (371,'Воблер Megabite Swing 85 F (85 мм, 10 гр) (15)','FS0003321','Витончений уокер Swing 85 F незамінний при поверхневому полюванні за щукою, окунем, жерехом. Там, де не дуже доречна шумна робота поппером, де поверхневий шар води над підводними чагарниками надто тонкий для класичних воблерів - виручить цей злегка вигнутий стік, що малює красиву "змійку" в такт посмикуванням вершини вудлища. Swing 85 чудово працює як на спокійному твічі з віддачею шнура, так і при високочастотному окуневому тремтіння. Управляється дуже легко, летить далеко і точно – полювання з такою принадою суцільне задоволення.
