INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (431,'Воблер Megabite Mini Shad 45 SP (45 мм, 4,3 гр, 0,5 m) (26)','FS0004058','Mini Shad 45 SP - універсальний приповерхневий ВУЛ-воблер, вельми варіативний по техніці анімації та швидкості проводки. Має власні коливання характерного малюнка і середньої інтенсивності, легко відгукується на ритмічну ривкову проводку, зображуючи красиву регулярну "змійку" без особливих викрутасів. Відмінно працює у стоячій воді, тримає струмінь аж до перебігу середньої сили. З його допомогою дуже ефективно облавлюється приповерхневий обрій до 0.5 м від поверхні. Дуже захоплююче берегове полювання з Mini Shad 45 SP в малій річці: по суті, достатньо однієї цієї моделі в декількох кольорах, щоб успішно полювати на всіх хижаків наших вод: не тільки щук і окунів, але й головня, язя, навіть жереха. Воблер чудово тримає паузу - тому дуже уловистий не лише влітку, а й у холодну пору року.
