INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (453,'Воблер Megabite Fatty Minnow 90 SP (90 мм, 15,8 гр, 1,3 m) (9)','FS0007133','Fatty Minnow 90 SP - досить великий мінноу середнього заглиблення, що має власну гру, але чудово працює і на твічінгу. Завдяки досить об''ємному тілу, приваблює хижака не тільки зигзагоподібним рухом на "змійці", але й амплітудними власними коливаннями. Прекрасно тримає паузу – тому дуже уловистий у холодну пору року. Дуже уловистий, хороший як "розвідник" при темповому облові значних площ.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (454,'Воблер Megabite LB Minnow 60 SP (60 мм, 3,2 гр, 0,8 m) (10)','FS0002301','LB Minnow 80 SP – спеціалізована твичева модель. Власні коливання виражені слабо, але на жорсткому хаотичному твічингу воблер здатний творити чудеса. Відмінно працює як у стоячій воді, так і на протязі. З його допомогою дуже ефективно облавлюється горизонт від 30 см до 1 м від поверхні (залежно від товщини шнура, що використовується, і нахилу вудилища під час проводки). Пріоритетна мета при використанні цієї приманки – зрозуміло, щука. Але не пропустить її і великий окунь, і навіть жерех - при полюванні за ним у невеликій річці. Воблер чудово тримає паузу - тому дуже уловистий в холодну пору року. LB Minnow 80 SP відмінно збалансований, стійке забарвлення, оснащений дуже якісною і надійною фурнітурою. Рекомендуємо застосовувати на твердому повідку довжиною не менше 12 см.','https://fishingstock.ua/upload/iblock/463/463e7215dc04d19c6eded67b165eb18f.jpg','шт.',280.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
