INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (472,'Воблер Megabite Booby 45 F (45 мм, 6,7 гр, 0.5 m) (10)','FS0002298','Booby 45 F - класичний кренк, простий в управлінні та дуже уловистий за всіма видами хижака, включаючи білого (головень, язь, жерех). Основна проводка - рівномірна, протягом дуже ефективна робота "на знесення" з контролем частоти биття приманки і невеликими хвилеподібними потяжками.
