INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (517,'Воблер Megabite Dandy 125 SP (125 мм, 28,2 гр, 1,2 m) (15)','FS0003307','Dandy 125 SP - великий мінноу, чудово "заточений" під джеркову, агресивну ривкову проводку. Будучи застосований на досить потужній і жорсткій снасті, він успішно складе конкуренцію уславленим "японцям" - Рудрам і Балісонгам, при цьому вигідно відрізняючись від них за ціною. Особливість воблера – відносно високе тіло, що забезпечує неповторні, дуже привабливі для хижака поздовжні погойдування корпусу як на ривках, так і під час паузи.
