INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (546,'Воблер Megabite Chip 40 F MR (40 мм, 3,75 гр, 1,0 m) (13)','FS0002999','Chip 40 F MR - мікрокренк із насиченою, яскраво вираженою власною грою. Найкраще підходить для лову голавля, окуня, невеликого жереха, щуки. Дуже хороший при лові в сильно запресингованих водоймищах, де на великі за розміром воблери хижак вже не реагує.
