INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (572,'Воблер Megabite Mystic 130 SP (130 мм, 18,4 гр, 0,5 m) (12)','FS0002784','Mystic 130 SP - оригінальний джерк, виконаний у популярній тригачковій схемі і тому володіє ідеальним балансуванням і чудовою реалізацією клювань. З кількістю клювань на цей воблер все також чудово - оскільки на жорсткому, хаотичному твічі він не поступається визнаним еталонам цієї групи приманок, 110м Вижнам і Рудрам, але при цьому йде набагато вище і дозволяє працювати в більш тонкому приповерхневому шарі води над чагарниками водної рослинності . Призначений для трофейного полювання – великий силует приманки привабливий для хижака гідного розміру, збільшені трійники надзвичайно гострі та дуже міцні.
