INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (673,'Приманка Bait Breath (Wonder Baits) TapTail 2,7" (10 шт) (#114)','FS00000565','Солодощі TapTail розроблені японським спортсменом-професіоналом Shunsuke Nomura для ситуацій, коли здивувати баса не можна вже нічим, але дуже потрібно. Розвиваючи відому конструктивну концепцію "бобрового хвостика", який надзвичайно ефективний пасивної риби при лові в щільному контакті з донним грунтом, нові TapTail дають рибалці можливість застосувати цей ефект не тільки в донному, але і в пелагічному джизі. Та бавовна хвостика об дно, яка так інтригує не лише баса, а й пасивних судаків, окунів, щук - TapTail видає, ударяючи лопатою об власний корпус! Для цього хвіст злаги зроблений подвійним, потужний хвостовий стібень підтримує "бобровий хвостик" знизу, служить тим самим майданчиком, по якому і проводиться необхідний ляпанець.
