INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (752,'Приманка Bait Breath Shift Tail 3" (8шт.) (S-07)','FS0010590','Універсальна приманка з характерною для віброхвостів «п''ятою» не така проста, як може здатися. Секрет її оригінальної гри - у значній довжині тонкої хвостової частини, яка на швидкісній проводці видає рівномірні, розгонисті коливання, підкоряючись законам гідродинаміки, а вертикальний "плавничок" вносить у цей рух вишукану високочастотну складову. Але варто уповільнити темп і перейти до анімації з "підривами", паузами - хвіст починає жити своїм життям, у його рухах дуже виразно проступають "черв''ячні" мотиви. Тому їстівку Shift Tail дуже цінують мисливці за судаком, чия пристрасть до різноманітних поєднань активної та пасивної анімації загальновідома, і чиї мінливі (навіть протягом одного дня) смаки можна задовольнити лише за допомогою вдумливої, творчої, варіативної проводки. Якщо ви не любите тягати з собою величезний кейс із силіконом, але прагнете максимальної різноманітності технік анімації - Bait Breath Shift Tail, безумовно, ваша приманка.','https://fishingstock.ua/upload/iblock/f63/f63f78a414cb61dcaded68caa945c7b7.jpg','шт.',195.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
