INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (821,'Приманка Bait Breath U30 Mosya 1,5" (14 шт.) (#106 Watermelon Seed)','FS00000561','Bait Breath "Mosya" - не просте силіконове "ракоподібне". Ця дуже специфічна приманка, розроблена для морського прибережного джигового лову, стала у нас одним із суперхітів легкого джига. Її головна особливість - максимальна схильність до зависають, "парячих" проводок на мінімальному завантаженні. Значна парусність та максимальна об''ємність Mosya дозволяє вести її невеликими підкидами дуже повільно, практично не торкаючись дна. Вона чудово працює як на стоячій воді, так і на слабкій течії, контрольований знесення цього рачка на шарнірному завантаженні буває дуже ефективний при річковій лові судака і великого окуня. Легке ворушіння вусиків, оснащених масивним "п''ятачком" додатково мотивує хижака до клювання, а чудові "сідние" якості силікону Bait Breath змушують його смакувати приманку, забуваючи про все...','https://fishingstock.ua/upload/iblock/bc0/bc074d47f8e3c5f186ab1c5d55844f72.jpg','шт.',253.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
