INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (860,'Приманка Bait Breath U30 Fish Tail Shad 2,8" (8шт.) (003 Solid Black)','FS0001162','Fish Tail Shad 2,8" - дуже вдала модифікація чудового складу Fish Tail. Нехай рибалка не вводить в оману крихітний хвостовий "п''ятачок" - досить активних коливань, характерних для приманок з власною грою, він все одно не зробить. Ні, це саме слаг - завдяки його хвостовій частині нам лише вдається внести в характерний для слогів малюнок різкої, ривкової придонної анімації, додаткову вібраційну складову... Іноді тільки цього не вистачає, щоб остаточно переповнити чашу терпіння пасивного хижака, що нерухомо стоїть біля дна... Відомі випадки застосування Fish Tail Shad на відповідальних турнірах з спінінгу, неодноразово ця незвичайна приманка приносила вмілому спортсмену дуже потрібний трофей.','https://fishingstock.ua/upload/iblock/2bb/2bb67d0f6bc1d11c75a6dc5995810d2c.jpeg','шт.',241.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
