INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (949,'Приманка Bait Breath Needle RealFry 2,5" Trout (12шт.) (Green (Lime))','FS0628124','Штучні черв''яки, є однією з найбільш уловистих приманок при лові ставкової та струмкової форелі. Незважаючи на відсутність власної гри, приманка Bait Breath Needle RealFry 2,5" Trout, виявилася до смаку обережній і хитрою рибі. Силіконові приманки часто виручають при повному безкльов''ї і завдяки бурхливій фантазії та майстерності створення анімації, вдається спровокувати хижачку на поклеві. Needle RealFry 2,5" Trout добре реагує на будь-які маніпуляції вудилищем. Також слід відзначити просочення і запах цих черв''яків. Для збереження якостей, що приваблюють, рекомендуємо зберігати приманки, тільки в рідній упаковці.','https://fishingstock.ua/upload/iblock/a5b/a5bba9b8bb1434c0845acbe29d9b591f.jpg','шт.',163.4,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
