INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (989,'Приманка Bait Breath Needle RealFry 2,5" Trout (12шт.) (129 Bubble Gum Pink)','FS0628121','Штучні черв''яки, є однією з найбільш уловистих приманок при лові ставкової та струмкової форелі. Незважаючи на відсутність власної гри, приманка Bait Breath Needle RealFry 2,5" Trout, виявилася до смаку обережній і хитрою рибі. Силіконові приманки часто виручають при повному безкльов''ї і завдяки бурхливій фантазії та майстерності створення анімації, вдається спровокувати хижачку на поклеві. Needle RealFry 2,5" Trout добре реагує на будь-які маніпуляції вудилищем. Також слід відзначити просочення і запах цих черв''яків. Для збереження якостей, що приваблюють, рекомендуємо зберігати приманки, тільки в рідній упаковці.','https://fishingstock.ua/upload/iblock/335/3350e8a7955d63dda88e8c2467ce6b0b.jpg','шт.',163.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
