INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1005,'Вудлище Yamaga Blanks Calista 710M TZ Nano','FSH001230','Yamaga Blanks Calista 710M TZ Nano – потужний універсал. Завдяки універсальній довжині підходить як для берегового, так і для лову човна. Вудилище має складний лад, що забезпечує хороший контроль приманки та чудові кидкові характеристики. Завдяки використанню технології NANO вдалося зменшити вагу бланка без втрати міцності. Дане вудлище легко справляється як із джигом, так і з ривковою анімацією великих воблерів.','https://fishingstock.ua/upload/iblock/a4a/a4a9c34096081bac4d48b2ae202919e5.jpeg, https://fishingstock.ua/upload/iblock/966/966bc1a3d90a04ea0302502e93c53b4f.jpeg, https://fishingstock.ua/upload/iblock/36c/36cf95fa3d5318d33b3c77570adb5cc8.jpeg, https://fishingstock.ua/upload/iblock/4ff/4ffa672586ab7a5b5a6e4564b59c44d5.jpeg','шт.',22506.0,1,206,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1006,'Вудлище Yamaga Blanks Calista 710M TZ Nano','','Yamaga Blanks Calista 710M TZ Nano – потужний універсал. Завдяки універсальній довжині підходить як для берегового, так і для лову човна. Вудилище має складний лад, що забезпечує хороший контроль приманки та чудові кидкові характеристики. Завдяки використанню технології NANO вдалося зменшити вагу бланка без втрати міцності. Дане вудлище легко справляється як із джигом, так і з ривковою анімацією великих воблерів.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1007,'Приманка Bait Breath T.T.Shad 2,4" (8 шт)','','Приманка Bait Breath T.T.Shad 2,4" виготовлена з урахуванням усіх новітніх тенденцій у цій галузі, всі способи збільшення її уловистості застосовані в конструкції дуже грамотно: - потужне, об`ємне тіло є хижакові ласим шматочком, гідним витрат енергії на кидок і захоплення видобутку; - кільцеві ребра, якими покрита приманка, дають правильні тактильні відчуття рибі, що клюнула, стимулюють її до утримання приманки в роті – а, крім того, створюють додаткову вібрацію водного середовища при проводці; - тонке хвостове стебло в поєднанні з широкою трикутною лопатею на кінці, дають приманці надзвичайно адекватну гру при проводці з будь-якою швидкістю, робота хвоста не збивається при перетині кордону струменів, і повільно, апетитно згасає на паузі. Для зручності рибалки віброхвіст оснащений усіма прорізами і виїмками під офсет. Фірмова їстівна формула BYS Mix Flavor забезпечує чудову уловистість приманки при лові щуки та (особливо!) великого судака.','https://fishingstock.ua/upload/iblock/c1e/c1eb98583fffbafe1174f35866c88a63.jpeg, https://fishingstock.ua/upload/iblock/3cc/3cce8b0279e25c5e5fbeea42e85e62a3.jpeg','шт.','',2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
