INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1078,'Флюорокарбон Intech FC Shock Leader 25м','','Intech FC Shock leader – флюорокарбон, новинка 2017 року. Черговий плід співпраці українських рибалок-спортсменів та японських інженерів. Intech FC виготовлений в Японії і незважаючи на невисоку вартість, має всі якості, властиві сучасним шоклідерам: - підвищену жорсткість; - абразивостійкість; - Точністю заявлених параметрів (товщини та розривного навантаження); - довговічність; - стійкість до UF-випромінювання; - Зручна розмотування: 10, 25 та 50 метрів; - широкий модельний ряд від 0.12 до 0.55 mm у перерізі;','https://fishingstock.ua/upload/iblock/ca9/ca903da46b3cab573c8a83bbfe47c351.jpeg','шт.','',3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
