INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1114,'Гачок Vanfook подвійний DW-31B Stealth Black','','Подвійний гачок Vanfook DW – 31B виконаний із високолегованої сталі, має ідеальне заточування. Двійник DW – 31B завдяки своїй формі відмінно підходить для використання під час виготовлення монтажів з м`якого пластику та поролону. Гачок виконаний з потужного дроту, міцності якого вистачить для того, щоб впоратися з трофеєм будь-якого розміру.','https://fishingstock.ua/upload/iblock/303/303c06b832b54d9428957f462b3c9f12.jpeg, https://fishingstock.ua/upload/iblock/b00/b006e9cde5f137f53946308c219414b7.jpeg','шт.',271.0,5,196,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1115,'Крючки Vanfook офсетные WORM35B Flat NS Black (#02 (8шт))','FS0001016','Ефективність роботи будь-якої приманки, оснащеної гачком Vanfook, є абсолютною. Патентований склад сталі, з якої виготовлені ці шедеври рибальського мистецтва, забезпечує неймовірну жорсткість та пружність при мінімальній товщині та масі гачка – отже, приманці забезпечена максимально легка та природна гра. Особлива форма жала і хімічна технологія його заточування дають ідеальну зацепистість, і доводять реалізацію клювань до абсолютного значення – а оскільки загартовуються ці крихітні вбивці за стародавніми японськими традиціями термообробки збройової сталі, затупити такий гачок практично неможливо. Застосовуйте гачки Vanfook у найвідповідальніших випадках спортивних змагань та рибальських експедицій – а якщо ви потребуєте стовідсоткової реалізації клювань на кожній рибалці, застосовуйте їх завжди!','https://fishingstock.ua/upload/iblock/09e/09e4540069570f54d9e466a7fc402644.jpeg','шт.',125.0,5,196,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
