INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1154,'Шнур плетений Intech All-Range PE X-4 150m','','Intech All-range PE X4 - це серія чотирижильних PE шнурів середнього цінового сегмента, що має високу якість. Маючи широкий модельний ряд, шнури All-range PE X4 зможуть укомплектувати будь-яку снасть, починаючи від ультралайту до суперважких снастей. У модельному ряду є шнури з перетином від 0,3 до 2,5 PE, з розривним навантаженням від 5lb (2 кг) до 26lb (11,8 кг). Універсальний PE X4 - має високу стійкість до стирання, тому він ідеально підходить для риболовлі в складних умовах: камені, черепашки, корчі. Цей шнур призначений для постійного використання в різних умовах для будь-яких методів лову: від класичного джигу до сучасного твічингу.','https://fishingstock.ua/upload/iblock/87e/87e7c6cdd84099450a176ed77b1666eb.jpeg','шт.',542.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
