INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1167,'Шнур плетений Intech FURIOS PE WX4 120m','','Intech Furios РЕ WX4 – найновіший плетений шнур, що виходить на рибальський ринок у 2016 році завдяки співпраці японських технологів концерну YGK та спортсменів-спінінгістів України. Ця плітка встановлює новий стандарт якості бюджетного шнура, який зовсім не обов`язково має бути середньою за своєю якістю. Сучасна технологія плетіння волокна запатентована концерном YGK під найменуванням WX4, дозволила отримати плетінку, що істотно перевершує давно представлені на ринку «народні» моделі шнурів. Сьогодні можна з упевненістю сказати, що Intech Furios – найтонший, найщільніший і найгладший шнур у своєму класі. І водночас – найдешевший! Інтек Фуріос - універсальна плетінка, що відмінно працює в спінінговій снасті будь-якого призначення і будь-якої потужності. Завдяки стійкому, не надто яскравому помаранчевому кольору забезпечує відмінні умови для візуального контролю проводки та положення приманки. У нашому рибальському інтернет-магазині ви завжди можете купити цей шнур для риболовлі у будь-якому розмірі. Випускається в розмотуванні 150 і 120 метрів, завтовшки від #0.3 до #2.0. Плетений шнур у Intech Furios РЕ WX4 у звітах: Блог Олега Сізона: - Камплица, Харьковская область - Горбатовка, Полтавская область','https://fishingstock.ua/upload/iblock/9bb/9bb3f0ba1a2bf928f7594c39b02944d3.jpeg','шт.',730.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
