INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1204,'Шнур плетений YGK Frontier Braid Cord X8 for Jigging 200m','','FRONTIER BRAIDCORD X8 for JIGGING – новий восьмижильний шнур YGK, новинка 2017 року. Шнур виготовлений із нового високомолекулярного поліетиленового волокна, що пройшов ряд випробувань та тестів, вивівши на ринок нові стандарти в серії для бюджетних плетених шнурів. Завдяки використанню нових матеріалів вдалося значно знизити ціну за збереження високих характеристик. Frontier braidcord X8 - це нове покоління шнурів, призначених для лову в абразивному середовищі. Так, цей восьмижильний шнур призначений саме для лову по каменях та черепашці. Завдяки плетенню з восьми ниток шнур має ідеально круглий переріз і мінімальний коефіцієнт розтяжності, завдяки чому можна досягти максимального контролю приманки при донному лові. Шнур має нове, максимально жорстке покриття, що значно підвищує стійкість до стирання та абразиву. Шнур виготовлений у Японії. Колір: мультиколор (змінює забарвлення через кожні 10м).','https://fishingstock.ua/upload/iblock/7be/7bed6a38e2585d464e0e3d15ce57c298.jpeg','шт.',1235.0,3,209,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
