INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1218,'Волосінь Intech Invision Ice Line 50m','','Intech ICE-Line - високоякісна моно волосінь, призначена для зимового лову. Лісочка була розроблена українськими рибалками спільно з інженерами японського концерну YGK і вироблена в Японії. Відмінними рисами Intech ICE-Line є: - Високий коефіцієнт розтяжності, що дозволяє амортизувати ривки риби та при мінімальному перерізі справлятися з великим трофеєм. - Відсутність пам`яті. Лісочка після змотування з бобіни або котушки витягується в пряму лінію, а не згортається в так званий «поросячий хвостик». - Високе розривне навантаження. - Висока міцність на вузлах. - Широка розмірна лінійка від 0.08мм до 0.33мм. Завдяки плідній співпраці вдалося досягти якості, яка до цього моменту не зустрічалася не тільки в рівному, а й у вищому ціновому сегменті.','https://fishingstock.ua/upload/iblock/2bb/2bb2e87661afc88ecacadf260f821f0e.png','шт.',65.0,6,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1219,'Мормышка Intech Ice Jig Шарик грань с петелькой ?5.0 (5шт)','','Мормышка Intech Ice Jig - предназначена для подледной ловли. Данный тип приманки зарекомендовал себя как самый уловистый для всех видов рыб. Чем уникальна мормышка Intech Ice Jig: • Надежный крючок. Мормышки оснащены японским крючком Hayabusa. • Уникальная технология прессовки. Мормышки Intech Ice Jig изготовлены по уникальной технологии прессовки, которая позволяет получить вольфрам высокой плотности. Удельный вес вольфрама в такой мормышке практически не отличается от точеного; • Щадящая пайка. Пайка крючка к телу мормышки происходит при сравнительно малых температурах, что позволяет сохранить все пружинящие свойства крючка (крючок не разгибается) и долговечность его покрытия. • Популярные модели. Отобраны самые интересные модели, которые популярны среди спортсменов и почитателей зимней рыбалки.','https://fishingstock.ua/upload/iblock/71a/71a51ae94eb68b87a7baa8a6c212ba19.jpeg','шт.','',6,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
