INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1263,'Блесна Yarie Ringo №704 30mm 3g (YM3)','FS0631064','Блешня Yarie Jespa Ringo - неймовірно уловиста блешня, має мінімальну підйомну силу на проводці і відмінно тримає заданий горизонт. Особливість геометрії забезпечує свої активну гру навіть на найповільнішій проводці, щоб спокусити максимально пасивну рибу. Кращі результати Yarie Jespa Ringo показує у лові форелі у стоячих водоймах у area-лові. Але також може бути використана і для лову голавля, окуня або жереха на малих та середніх річках. Широка палітра кольорів дозволить вибрати приманку на будь-який смак та під найрізноманітніші умови лову.','https://fishingstock.ua/upload/iblock/77a/77acfae542434f5d951e943793d39277.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
