INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1274,'Блесна Yarie B-Tap №705 21mm 1.2g (#50)','FS0630993','Блешня Yarie Jespa B-Tap - блешня, яка розроблена досвідченим спортсменом-фореляником Yoshimichi Hasegawa для донного лову та джигової анімації. Особливість приманки у спеціальному кріпленні гачка з одного боку. При такому способі кріплення гачок завжди дивиться вгору, зводячи до мінімуму зачепи за дно сміття. Блешня Yarie Jespa B-Tap максимально підходящий варіант для лову в найскладніших умовах. Під час анімації на підмотуванні блешня демонструє заворожливу гру при мінімальній швидкості, як у моделі Yarie Jespa Pirica More. Приманка здатна виручити при найнижчій активності риби, а широка гама кольорів не залишить байдужим жодного рибалки.','https://fishingstock.ua/upload/iblock/1a1/1a19f80e0eda17fe8fd47f016e47b291.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
