INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1297,'Блесна Yarie T-Surface №709 25mm 1.2g (#4)','FS0630943','Yarie Jespa T-Surface - блешня, спеціально розроблена для підповерхневого лову форелі. Робочий горизонт цієї блешні - лов форелі на глибині до 20 см. Принада має велике тіло і рухливу гру, що чудово приваблює хижака і провокує пасивну форель на клювання. За такої малої ваги, блешня Yarie Jespa T-Surface №709 демонструє відмінну дальність закидання, не збиваючись і не змінюючи положення в польоті. Коли форель активно годується біля поверхні - ця приманка здатна стати кращою у коробці та вивести у переможці.','https://fishingstock.ua/upload/iblock/d02/d02361a1d240808ae4eb7ec8c337eda2.jpg','шт.',186.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
