INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1305,'Блесна Yarie T-Fresh №708 25mm 2g (P2)','FS0631092','Блешня Yarie Jespa T-Fresh - широкотіла блешня з опуклим профілем. Насамперед, дана модель призначена для ставкового лову форелі. Принада демонструє активну гру на повільній проводці, широко розгойдуючись відмінно приваблює активну рибу з великої відстані. При однакових габаритах за рахунок різної товщини блешня Yarie Jespa T-Fresh має різну вагу. Легка блешня буде доречніша на мілководді для спокуси вибагливої риби на найповільнішій анімації. Більш важка блешня підійде для швидкісного облова та використання на великих глибинах.','https://fishingstock.ua/upload/iblock/ade/adedddfa2a289f1e46fc527040c13cb3.jpg','шт.',255.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
