INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1326,'Блесна Yarie Pirica More №702 29mm 2,2g (V2)','FS0631008','Блешня Yarie Jespa Pirica More – невелика легка блешня для лову форелі. Ці блешні були спеціально розроблені для участі у змаганнях та турнірах. Максимально ефективно працює на повільній проводці. Завдяки продуманій формі на паузі вона не падає каменем, а пурхає, демонструючи хаотичність рухів. При проведенні такої блешні будуть доречні паузи з віддачею шнура. На протязі вона показує стабільну гру, не збивається та не штопорить. Блешня випускається в одному розмірі, але з різною вагою. Відмінна універсальна приманка, що підходить для лову безлічі риб.','https://fishingstock.ua/upload/iblock/53a/53ab1c057a303d108aa09033c9efe4c0.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
