INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1358,'Блесна Yarie Ringo №704 28mm 2,1g (C64)','FS0631046','Блешня Yarie Jespa Ringo - неймовірно уловиста блешня, має мінімальну підйомну силу на проводці і відмінно тримає заданий горизонт. Особливість геометрії забезпечує свої активну гру навіть на найповільнішій проводці, щоб спокусити максимально пасивну рибу. Кращі результати Yarie Jespa Ringo показує у лові форелі у стоячих водоймах у area-лові. Але також може бути використана і для лову голавля, окуня або жереха на малих та середніх річках. Широка палітра кольорів дозволить вибрати приманку на будь-який смак та під найрізноманітніші умови лову.','https://fishingstock.ua/upload/iblock/6fb/6fb38eeccfed7ee81da74a2cd727b74a.jpg','шт.',169.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
