INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1379,'Блесна Yarie Pirica More №702 29mm 2,6g (E71)','FS0630923','Блешня Yarie Jespa Pirica More – невелика легка блешня для лову форелі. Ці блешні були спеціально розроблені для участі у змаганнях та турнірах. Максимально ефективно працює на повільній проводці. Завдяки продуманій формі на паузі вона не падає каменем, а пурхає, демонструючи хаотичність рухів. При проведенні такої блешні будуть доречні паузи з віддачею шнура. На протязі вона показує стабільну гру, не збивається та не штопорить. Блешня випускається в одному розмірі, але з різною вагою. Відмінна універсальна приманка, що підходить для лову безлічі риб.','https://fishingstock.ua/upload/iblock/6ba/6bab5302198c421c4a534eb46034d2a8.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
