INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1405,'Шнур плетеный YGK Frontier Braid Cord X8 for Shore 150m (1.0 (16lb / 7.26kg))','FS0630491','FRONTIER BRAIDCORD X8 for SHORE – новий восьмижильний шнур від YGK, новинка 2017 року. У новому шнурі YGK використано нове високомолекулярне поліетиленове волокно, яке пройшло низку випробувань та тестів, вивівши на ринок новий стандарт плетених шнурів. Завдяки використанню нових матеріалів вдалося значно знизити ціну за збереження високих характеристик. Frontier braidcord X8 - це нове покоління шнурів, призначених для лову з берега в абразивному середовищі. Так, цей восьмижильний шнур призначений саме для лову по каменях та черепашці. Завдяки плетенню з восьми ниток шнур має ідеально круглий переріз і чудові польотні якості, а завдяки новому максимально жорсткому покриттю значно підвищена стійкість до стирання. Також завдяки своїй жорсткості шнур значно менше плутається. Шнур виготовлений у Японії.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1406,'Джиг-пуля Intech (1шт) №01','','Джиг-куля Intech - якийсь симбіоз класичної джиг-головки та техаського оснащення. Вже довгий час техас та інші рознесені монтажі вважаються не спортивними, та й час на їх в`язання для облова закаряженої ділянки або острівця латаття буває даремно витраченим, не кажучи вже про невиразний контакт ковзної кулі з дном. Для полегшення життя тепер можна скористатися джиг-кулею Intech, яка є обтічний, кулеподібний вантаж з жорстко закріпленим гачком офсетним. Обтічна форма дозволить уникнути неприємних зачепів, а жорстко закріплений гачок Vanfook багаторазово підвищить реалізацію клювань.','https://fishingstock.ua/upload/iblock/845/84580a7da4fb276563f7dd9d0d163bde.jpeg','шт.',26.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
