INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1426,'Приманка Bait Breath Skeleton Shrimp SSP (8шт.)','','Skeleton Shrimp SSP - фантазійна приманка, що імітує ракоподібне. Рухливі ніжки приманки активно вібрують під час проведення. Приманка не вимоглива до ваги завантаження та типу монтажу. Класична шарнірна сполука, кароліна або техас на повну розкриє потенціал приманки. 2.7 дюйма універсальний розмір, що дозволяє полювати на окуня, щуку та судака цілеспрямовано.','https://fishingstock.ua/upload/iblock/d60/d6019487733ea7ac74ec9b2660d76714.jpeg','шт.',252.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
