INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1432,'Приманка Intech Slim Shad 2,5"(12 шт)','','Intech Slim Shad – класичної форми віброхвіст, який став ще одним впевненим кроком наших виробників на шляху створення досконалої приманки. Унікальність властивостей пояснюються простим рішенням – хвостова частина та саме тіло розділене тонкою перегородкою, завдяки якій коливання Slim Shad виходять м`якими, високочастотними, але не надто агресивними. Тіло Slim Shad виглядає досить об`ємним і м`ясистим, проте аеродинамічні властивості при цьому дуже хороші, що дозволяє Slim Shad успішно використовувати на дальній дистанції. Завдяки спеціальній канавці на спинці Slim Shad чудово підходить для офсетних монтажів. Хвіст-«п`ятка» має невеликий розмір і з`єднаний з принадою за досить великим перерізом. З одного боку, це надає додаткової міцності, а з іншого – забезпечує малу амплітуду коливань за їх високої частоти.','https://fishingstock.ua/upload/iblock/64c/64c281b4a3f4af5e5e50ffa50df9daf2.jpeg, https://fishingstock.ua/upload/iblock/491/4910c77db020c70acc14b1a153957dff.jpeg, https://fishingstock.ua/upload/iblock/8dd/8dd03d1f4a794b0cf55a5e2b71a4b5f0.jpeg, https://fishingstock.ua/upload/iblock/af3/af32d6e60992e11defc90846f7dd3d0a.jpeg','шт.',60.0,2,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
