INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1737,'Виброхвост Sawamura One''Up Shad 2" (9шт.) (037)','FS0631407','One''Up Shad - яскравий представник нового покоління віброхвостів, чия уловистість забезпечується гармонійним поєднанням форми, складу матеріалу та забарвлення приманки. У цій моделі розробнику вдалося домогтися поєднання разючої свободи рухів хвостової частини віброхвоста і його відмінної живучості - секрет полягає в помітній "талії", що розділяє силіконову рибку на приблизно дві рівні частини і дає додаткову свободу її хвостику. Хвостова лопать невелика - тому для своїх коливань приманки характерна досить висока частота, властива руху втомленої рибки, вже нездатною довго йти від погоні. Для оснащення офсетником носова частина One''Up Shad посилена, а на спинці його виконано поглиблення, що забезпечує незачіплюваність гачка при контакті з водною рослинністю або коряжником. Унікальна їстівна формула силікону Sawamura захищена відповідними патентами, її ефективність перевірена європейськими рибалками у найрізноманітніших умовах наших водойм та визнана чудовою. Портрет приманки-бестселера довершує оригінальна палітра кольорів, що поєднують натуральність і помітність, особливо ефективні комбіновані двокольорові зразки з дуже гармонійним поєднанням темної спинки та прозорого черевця. Мерехтіння блискіток, укладених усередині віброхвоста, створює абсолютно адекватне відчуття живого руху - хижак атакує One''Up Shad жадібно, впевнено, миттєво переходячи до агресії навіть із сонного стану.
