INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1896,'Приманка Intech Slim Shad 5" (5 шт)','','Intech Slim Shad – класичної форми віброхвіст, який став ще одним впевненим кроком наших виробників на шляху створення досконалої приманки. Унікальність властивостей пояснюються простим рішенням – хвостова частина та саме тіло розділене тонкою перегородкою, завдяки якій коливання Slim Shad виходять м`якими, високочастотними, але не надто агресивними. Тіло Slim Shad виглядає досить об`ємним і м`ясистим, проте аеродинамічні властивості при цьому дуже хороші, що дозволяє Slim Shad успішно використовувати на дальній дистанції. Завдяки спеціальній канавці на спинці Slim Shad чудово підходить для офсетних монтажів. Хвіст-«п`ятка» має невеликий розмір і з`єднаний з принадою за досить великим перерізом. З одного боку, це надає додаткової міцності, а з іншого – забезпечує малу амплітуду коливань за їх високої частоти.','https://fishingstock.ua/upload/iblock/e7d/e7d460d175d3c0f81aefea0bf0e535ec.jpeg, https://fishingstock.ua/upload/iblock/57b/57b48e6fc5eb22a793d92165ea376ef6.jpeg, https://fishingstock.ua/upload/iblock/e7c/e7cc9dd492370e050587761d59bf3ec4.jpeg','шт.',120.0,2,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
