INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1957,'Воблер Megabite Deep Runner 600 F (80 мм, 26.7 гр, 6 m) (6)','FS0632990','Воблер Megabite Deep Runner 600 F - це плаваючий класичний кренк, що має витягнуте бочкоподібне тіло і досить велику лопату, для заглиблення до шести метрів. Восьмисантиметрове тіло та вага 26,7 грам дозволяють закидати воблер точно, на дальню відстань. Принада оснащена двома добре підібраними за розміром та гострими трійниками, має реалістичні очі та гарні забарвлення у різних варіантах, які довго прослужать при активному використанні воблера. Активна гра воблера Megabite Deep Runner добре підходить як при лові тролінгом, так і при кастинговій рибалці. При використанні такої приманки слід враховувати сильний опір під час проведення і використовувати відповідні спінінги, які ви можете знайти в нашому інтернет магазині. Завдяки плаваючій здатності, приманку можна проводити в різних горизонтах води і тим самим урізноманітнити проводку. Використовуючи воблер Megabite Deep Runner 600 F, часто стаєш володарем гідної щуки та судака, заради яких ми й ходимо на рибалку.','https://fishingstock.ua/upload/iblock/9c8/9c8c6db0770234bc06ab3a17388e293b.jpeg','шт.',361.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
