INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1967,'Воблер Megabite Bite 50 F (50 мм, 4,3 гр, 1,5 m) (24)','FS0632696','Bite 50 F - глибоководна модель, призначена для облова придонних горизонтів при загальній глибині до 2 - 2,5 м. Його робочий горизонт 1,5 м. його застосування: що товщі нитка, то вище піде воблер. При лові на протязі в більшості випадків кращою проводкою буде «м''який твічинг», а при лові щуки та окуня у стоячій воді «жорсткий твічинг». Якщо дно в місці лову жорстке, істотно підвищити уловистість Bite можна за допомогою максимального заглиблення аж до контакту з ґрунтом: ідеально, якщо за всю проводку воблер 3-4 рази торкнеться дна, піднімаючи легку каламуту. Особливо небайдужий до такої проводки судак. Воблер відмінно збалансований, стійке забарвлення, оснащений дуже якісною і надійною фурнітурою. Рекомендуємо застосовувати на жорсткому повідку завдовжки не менше ніж 10 см.','https://fishingstock.ua/upload/iblock/84a/84a566ef4eefe32bf5cdc2e0d9801ac3.jpg','шт.',280.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
