INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1984,'Воблер Megabite Booby 50 F (50 мм, 9,4 гр, 0.7 m) (6)','FS0632968','Booby 50 F - досить великий кренк, простий в управлінні і дуже уловистий по всіх видах хижака, включаючи білий (головень, язь, жерех). Основна проводка - рівномірна, протягом дуже ефективна робота "на знесення" з контролем частоти биття приманки і невеликими хвилеподібними потяжками. Застосовується за бажання цілеспрямовано полювати на великого хижака, що стоїть на мілководді або в поверхневих шарах.
