INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1991,'Воблер Megabite Booby Zero F (45 мм, 6,8 гр, 0,1 m) (A_1)','FS0632718','Booby Zero - поверхневий кренк, що успішно становить конкуренцію топвотерам при лові в найдрібніших і зарослих ділянках водойми. Його перевага перед попперами та уокерами – у простоті управління, адже для виходу цієї приманки на найефективніший малюнок її анімації досить просто обертати ручку котушки. Може "вистрілити" і на течії при лові "на ляпанець" голавля і жереха, особливо поряд з укриттями риби - гілками, що нависають, підмитими "козирками", коряжником.
