INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1997,'Воблер Megabite Chip 40 F MR (40 мм, 3,75 гр, 1,0 m) (A_15)','FS0632729','Chip 40 F MR - мікрокренк із насиченою, яскраво вираженою власною грою. Найкраще підходить для лову голавля, окуня, невеликого жереха, щуки. Дуже хороший при лові в сильно запресингованих водоймищах, де на великі за розміром воблери хижак вже не реагує.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (1998,'Воблер Megabite Chip 40 F MR (40 мм, 3,75 гр, 1,0 m) (A_29)','FS0632732','Chip 40 F MR - мікрокренк із насиченою, яскраво вираженою власною грою. Найкраще підходить для лову голавля, окуня, невеликого жереха, щуки. Дуже хороший при лові в сильно запресингованих водоймищах, де на великі за розміром воблери хижак вже не реагує.
