INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2033,'Воблер Megabite Fatty Minnow 90 SP (90 мм, 15,8 гр, 1,3 m) (24)','FS0632994','Fatty Minnow 90 SP - досить великий мінноу середнього заглиблення, що має власну гру, але чудово працює і на твічінгу. Завдяки досить об''ємному тілу, приваблює хижака не тільки зигзагоподібним рухом на "змійці", але й амплітудними власними коливаннями. Прекрасно тримає паузу – тому дуже уловистий у холодну пору року. Дуже уловистий, хороший як "розвідник" при темповому облові значних площ.
