INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2051,'Воблер Megabite Mystic 120 SP (120 мм, 14,8 гр, 0,5 m) (6)','FS0633006','Mystic 120 SP - оригінальний легкий джерк, виконаний в популярній тригачковій схемі і тому володіє ідеальним балансуванням і чудовою реалізацією клювань. З кількістю клювань на цей воблер все також чудово - оскільки на жорсткому, хаотичному твічі він не поступається визнаним еталонам цієї групи приманок, 110м Вижнам і Рудрам, але при цьому йде набагато вище і дозволяє працювати в більш тонкому приповерхневому шарі води над чагарниками водної рослинності .
