INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2063,'Воблер Megabite Piccolino 40 SP (40 мм, 2,6 гр, 0,3 m) (A_1)','FS0632862','Piccolino 40 SP - ідеальний ультралайтовий воблер, що поєднує в одній моделі переваги трьох популярних класів: мінноу, шедів та кренків. За варіативністю проводки йому просто немає рівних: рівномірна, стоп-н-гоу, твічінг, робота на знесення, зимовий спінінг з величезними паузами... все йому по плечу, завжди спокусить окуня, щучку чи голавля. Кілька Piccolino 40 SP в різних кольорах цілком достатньо для того, щоб наповнити літній день на річці неймовірною різноманітністю проводок і клювань. Воблер добре працює у стоячій воді, тримає струмінь аж до перебігу середньої сили. З його допомогою дуже ефективно облавлюється приповерхневий обрій до 0.5 м від поверхні. Незважаючи на крихітний розмір, принада має пристойні польотні якості
