INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2083,'Воблер Megabite Popsy Max 80 F (80 мм, 18,4 гр) (17)','FS0633027','Великий і важкий Popsy Max 80 F - спеціальна приманка щука, що гарантує трофей при літній рибалці на великих мілководдях. Летить чудово, керується дуже легко, чітко реагуючи на ривки та закликаючи риб гучним бульканням. Атака щуки на Popsy Max видовищна і захоплююча - в жодному разі не поспішайте з підсіканням, обов''язково дочекайтеся відчуття удару, інакше ризикуєте висмикнути поппер прямо з широко розкритої пащі хижачки.
