INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2092,'Воблер Megabite Swing 105 F (105 мм, 16,3 гр) (17)','FS0633031','Великий уокер Swing 105 F необхідний рибалці, який зібрався цілеспрямовано полювати за щукою гідного розміру. Вальяжна "змійка", яку він малює на поверхні неглибокої водойми, викликає у хижачки непереборне бажання покарати вгодовану рибку за таку втрату обережності - в результаті спінінгісту гарантований видовищний вихід, потужний удар і відчуття від боротьби і перемоги.
