INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2192,'Крючки Vanfook тройные DT-45B NS Black (#06 (7шт))','FS0633692','Ефективність роботи будь-якої приманки, оснащеної гачком Vanfook, є абсолютною. Патентований склад сталі, з якої виготовлені ці шедеври рибальського мистецтва, забезпечує неймовірну жорсткість та пружність при мінімальній товщині та масі гачка – отже, приманці забезпечена максимально легка та природна гра. Особлива форма жала і хімічна технологія його заточування дають ідеальну зацепистість, і доводять реалізацію клювань до абсолютного значення – а оскільки загартовуються ці крихітні вбивці за стародавніми японськими традиціями термообробки збройової сталі, затупити такий гачок практично неможливо. Застосовуйте гачки Vanfook у найвідповідальніших випадках спортивних змагань та рибальських експедицій – а якщо ви потребуєте стовідсоткової реалізації клювань на кожній рибалці, застосовуйте їх завжди!','https://fishingstock.ua/upload/iblock/5c7/5c744fd78b425c3bd36963b0c25cdd0c.jpeg','шт.',240.0,5,196,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
