INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2202,'Гачок двійний Intech Longaff DFV-23SB','','Двійники Longaff DFV-23SB виготовлені на японському заводі Vanfook, з найякіснішої сталі, якій байдуже будь-який трофей, а гострота заточування дозволяє зачепити будь-яку рибу навіть без якісної підсічки. Двійник - частина монтажу, який дарує рибалці перевагу перед одинарним джиговим або офсетним монтажем. Вся перевага в тому, що при падінні на дно одинарник як правило ляже на бік, а двійник виставить щонайменше одне з тис нагору. Саме цей момент може грати вирішальну роль при клювання, або навіть просто притискати на дні хижаком. У продажу є двійники з подовженим цівкою, що важливо при оснащенні довгих приманок. Всі двійники Intech Longaff – це результат своєчасної розробки рибалок-експертів нашої компанії та заводу Vanfook.','https://fishingstock.ua/upload/iblock/8e2/8e2c8f604a396dfa1c96e65561e160b1.jpeg','шт.',150.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
