INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2217,'Воблер Megabite Jerkbite 65 SP (65 mm, 5.9 g, 1.0 m) (1)','FS0633200','Megabite Jerkbite 65 SP имеет нейтральную степень плавучести и лопасть, заглубляющую его до одного метра. Можно сказать, что данная модель будет грозой мелководий для щуки и окуня средних размеров. Как следует из названия, данный воблер создан для рыбковых техних проводок, при которых он совершает развороты в разные стороны и аппетитно покачивает боками. Длина 65мм в период бесклевья может выручить и сподвигнуть не берущего хищника на поклевку, когда не клюет на обычные твичинговые околодесятисантиметровые размеры воблеров.','https://fishingstock.ua/upload/iblock/aa6/aa674912161b5381525ef7a7f360475d.jpg','шт.',289.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
