INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2224,'Воблер Megabite Jerkbite 65 SP (65 mm, 5.9 g, 1.0 m) (R39)','FS0633205','Megabite Jerkbite 65 SP имеет нейтральную степень плавучести и лопасть, заглубляющую его до одного метра. Можно сказать, что данная модель будет грозой мелководий для щуки и окуня средних размеров. Как следует из названия, данный воблер создан для рыбковых техних проводок, при которых он совершает развороты в разные стороны и аппетитно покачивает боками. Длина 65мм в период бесклевья может выручить и сподвигнуть не берущего хищника на поклевку, когда не клюет на обычные твичинговые околодесятисантиметровые размеры воблеров.','https://fishingstock.ua/upload/iblock/a0f/a0fdcb61f02e6c31f3235ccf4bc50d5c.jpg','шт.',289.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2225,'Воблер Megabite LB VIB 75 S Sinking (75 mm, 21 g, 8 m) (1)','FS0633224','Megabite LB VIB 75S - раттлін, який має вагу 21г і чудово підходить для більшості водойм із чистим дном. Якщо глибина лову менше трьох метрів, то він чудово працюватиме на рівномірній проводці. Якщо глибини в місці лову великі, то ловити потрібно простою сходинкою: два обороти ручки котушки - пауза. Довжина 7,5см є оптимальною для щуки та судака. Має відмінні польотні характеристики. На падінні похитує боками, тому клювання на падінні - не рідкість.','https://fishingstock.ua/upload/iblock/eb7/eb7e3c40bcb1b957e85ae8cd26fcb1a6.jpg','шт.',274.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
