INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2229,'Воблер Megabite Minnowing 65 SP (65 mm, 5.4 g, 0.8 m) (217)','FS0633210','Megabite Minnowing 65 SP має нейтральний ступінь плавучості та лопаті, що заглиблює його майже до одного метра. Можна сказати, що дана модель буде грозою мілководдя для щуки та окуня середніх розмірів. Як випливає з назви, даний воблер створений для ривкових технічних проводок, при яких він робить розвороти в різні боки і апетитно похитує боками. Довжина 65мм в період безкльвів може виручити і спонукати хижака, що не бере на клювання, коли не клює на звичайні твічингові близькодесятисантиметрові розміри воблерів. Має систему далекого закидання.','https://fishingstock.ua/upload/iblock/8df/8dfb8b0379520e8b237f6c3b1227d23a.jpg','шт.',289.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
