INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2233,'Воблер Megabite Minnowing 65 SP MR (65 mm, 5.5 g, 1.5 m) (1)','FS0633211','Диповий воблер MEGABITE MINNOWING 65 SP MR заглиблюється до півтора метра і є одним з кращих при лові великого окуня або щуки, що не бере, на глибині до 2м. Цей суспендер любить агресивне ривкове проведення з рідкісними короткими паузами. Його також можна використовувати для виведення окуня з пасивного стану - пари проводок активного твічингу, а потім уже починати робити не сильні ривки з паузами та ворушіннями. Воблер має просунуту систему далекого закидання, що складається з вольфрамового циліндра на титановому дроті, який при закиданні зміщується в хвостову частину. Це дозволяє воблер летіти далеко і точно.','https://fishingstock.ua/upload/iblock/779/779665a2e655c1dec44d4e2bb96f80d1.jpg','шт.',289.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
