INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2246,'Воблер Megabite Samba 100 F (60 mm, 12,5 g, 1 m) (1)','FS0633178','Megabite Samba 100 F - товстий кренк, що має гарні польотні характеристики. Даний кренк повільно спливає на паузах, тому добре підходить для лову на зарослих мілководдях: якщо воблер уперся в перешкоду, то достатньо зробити паузу і продовжувати проводку. Воблер добре тримає течію.','https://fishingstock.ua/upload/iblock/bce/bcebddbed9c7bca32820f05334bd2764.jpg','шт.',286.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
