INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2260,'Воблер Megabite Sardine 110SP (110 mm, 13.7 g, 1.2 m) (1)','FS0631150','MEGABITE SARDINE 110SP має вагу 14г, нейтральну плавучість та заглиблення до 1,2 метра. Цей мінноу має чудові польотні характеристики з огляду на наявність системи далекого закидання. Найбільшої уловистості цієї моделі можна досягти, роблячи ривкові проводки: зазвичай це два ривки та пауза різної довжини. Розмір 110 допоможе розворушити пасивну рибу, коли вона відмовляється клювати на старшого брата у 130 довжині.','https://fishingstock.ua/upload/iblock/9d8/9d838c1a7f5877a59643f8e2d2e807ef.jpg','шт.',322.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
