INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2270,'Воблер Megabite Sardine 130SP (130 mm, 19.7 g, 1.8 m) (1)','FS0633166','MEGABITE SARDINE 130SP має вагу 18г, нейтральну плавучість та заглиблення майже до двох метрів. Цей мінноу має чудові польотні характеристики з огляду на наявність системи далекого закидання. Найбільшої уловистості цієї моделі можна досягти, роблячи ривкові проводки: зазвичай це два ривки та пауза різної довжини. Чим активніша риба. тим агресивніше необхідні ривки і коротше паузи. Коли хижак пасивний, все необхідно робити навпаки - ривки робити плавно і паузи збільшувати.','https://fishingstock.ua/upload/iblock/093/0939269dee9964a204a98aa8052aece3.jpg','шт.',337.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
