INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2278,'Воблер Megabite Shiner 60 SP (60 mm, 7.5 g, 2.5 m) (17)','FS0631154','MEGABITE SHINER 60 SP (60 MM, 7.5 G, 2.5 M) має нейтральний ступінь плавучості та лопаті, що заглиблює його до 2,5 метра. Незважаючи на довгу лопату, воблер чудово літає і можна сказати, що він буде грозою вгодованих окунів, головоломкою та щуком. Максимально ефективно його використовувати можна через два види проводок: спочатку можна провести його простим кренковим рівноміром, а потім спробувати ривкові проводки з паузами.','https://fishingstock.ua/upload/iblock/60d/60d1c90c52a4462eef5471950887473c.jpg','шт.',292.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
