INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2315,'Воблер Megabite Bite 110 SP ( 110мм, 23,6гр, 6m) (1)','FS0633248','Воблер Megabite Bite 110SP – унікальний великий мінноу, справжній вбивця трофейної щуки та судака. При першому ж погляді на приманку зрозуміло, що на глибоководному тролінгу вона ні в якому разі не вдарить в бруд обличчям - з такою широкою і довгою лопатою догляд на шестиметрову глибину проблем не складає, і навіть великі трійники цілком застраховані від зачепу за корч, що недоречно підвернувся. Перекинувшись через перешкоду, воблер негайно продовжить свою подорож перевалку, гудячи великими кулями і недбало помахуючи хвостовою частиною. Навіть потужний повідець не спотворить його спокійну, впевнену гру – економити на його довжині та міцності не варто, адже мішенню Bite є хижак по-справжньому трофейний: щука, судак, сом.
