INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2366,'Воблер Megabite Swing 85 F (85 мм, 10 гр) (R39)','FS0632940','Витончений уокер Swing 85 F незамінний при поверхневому полюванні за щукою, окунем, жерехом. Там, де не дуже доречна шумна робота поппером, де поверхневий шар води над підводними чагарниками надто тонкий для класичних воблерів - виручить цей злегка вигнутий стік, що малює красиву "змійку" в такт посмикуванням вершини вудлища. Swing 85 чудово працює як на спокійному твічі з віддачею шнура, так і при високочастотному окуневому тремтіння. Управляється дуже легко, летить далеко і точно – полювання з такою принадою суцільне задоволення.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2367,'Джиг-головка Intech Tournament DJ-Head 31 №1/0','','Головною перевагою джиг-головки Intech DJ-Head є те, що гачок вироблений японським концерном Vanfook, який є лідером у виробництві високоякісних гачків із найстарішим хімічним заточенням. Таке заточення в комплексі з міцною сталлю дають можливість надійно просікти будь-яку, найкісткішу пащу і впевнено втримати трофей будь-яких розмірів до моменту зустрічі його з підсаком.','https://fishingstock.ua/upload/iblock/9fb/9fb97ea324a0a352824c99f4a6feda49.jpeg','шт.',62.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
