INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2414,'Вудлище Yamaga Blanks Blue Current TZ BLC-83/TZ Nano Flex','FSH002569','Yamaga Blanks Blue Current TZ BLC-83/TZ Nano Flex - оновлена версія найуніверсальнішого (на думку спортсменів-береговиків) вудилища. Вудлище має новий матеріал бланка з використанням технології Nano, що зробило його більш надійним та чутливим. Коли не відомо, яка риба ловитиметься, дане вудлище дозволить підлаштуватися і під щуку, і під окуня і навіть дрібного судака. У такій довжині даний береговик заслуговує на приставки "супер-дальнобійний" і що саме головне - цей спінінг при закиданні зовсім не напружує рибалки: навіть при несильному зусиллі закидання ця катапульта зробить все сама, навантажиться і вистрілить на максимальну дальність будь-якою вагою з діапазону тесту. Верх тіста до 10,5 г - (це вантаж до 8 г + дрібний силікон) ну а по низах це унікальне вудлище дозволить ловити навіть на блешні 0,3 г зі шматочком їстівного силікону. Вудилищ з таким довгим діапазоном реального тесту у світі - на пальцях руки порахувати. Тому якщо ви хочете зловити кілька видів риби на одне вудлище на одній рибалці, то Yamaga Blanks Blue Current TZ BLC-83/TZ Nano Flex – ідеальний вибір.','https://fishingstock.ua/upload/iblock/a92/a92822c5d78701868890617854f3ff56.jpeg','шт.',20549.0,1,206,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
