INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2520,'Крючки Vanfook офсетные WORM55R Red (#4/0 (5шт))','FS0634137','Ефективність роботи будь-якої приманки, оснащеної гачком Vanfook, є абсолютною. Патентований склад сталі, з якої виготовлені ці шедеври рибальського мистецтва, забезпечує неймовірну жорсткість та пружність при мінімальній товщині та масі гачка – отже, приманці забезпечена максимально легка та природна гра. Особлива форма жала і хімічна технологія його заточування дають ідеальну зацепистість, і доводять реалізацію клювань до абсолютного значення – а оскільки загартовуються ці крихітні вбивці за стародавніми японськими традиціями термообробки збройової сталі, затупити такий гачок практично неможливо. Застосовуйте гачки Vanfook у найвідповідальніших випадках спортивних змагань та рибальських експедицій – а якщо ви потребуєте стовідсоткової реалізації клювань на кожній рибалці, застосовуйте їх завжди!','https://fishingstock.ua/upload/iblock/c36/c366ed5b1a8f6d0d464c65492a6e037e.jpg','шт.',145.0,5,196,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
