INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2577,'Приманка Bait Breath U30 Needle 2,5" (20 шт.) (113 Motor Oil)','FS0634196','Для лову на ближній дистанції донним УЛ-джигом - це, безперечно, приманка №1. Її особлива цінність - в ефективності саме за пасивним хижаком (у першу чергу, окуню), U30 Needle 2,5" дозволяє рибалці з честю вийти з ситуації повного безкльов''я на риболовлі, постійно рятує спортсменів на відповідальних турнірах. Цього дуже реалістичного черв''яка частенько с''є більш серйозні хижаки - судак і навіть щука, нерідкі також випадки упіймання на цю приманку ультралайтової спінінгової снастю нехижих (іноді досить великих) риб. за процесом поглинання окунем смачного черв''яка.Живучість Needle також на висоті, десяток зловлених смугастих красенів - для кожної з цих приманок звичайна справа. Рекомендовані прийоми анімації - повільний донний "пунктир" на легкому вантажі, зі значними паузами. у товщі води... арсенал проводок, на яких U30 Needle 2,5" працює чудово, надзвичайно широкий.','https://fishingstock.ua/upload/iblock/3f1/3f14c4db3cf3813737e77eae79e2c3ca.jpg','шт.',219.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
