INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2580,'Приманка Bait Breath E.T.Shad 2,8" (8 шт)','','E.T.Shad 2,8 - нова модель японського виробника Bait Breath, яка пожвавила лінійку віброхвостів. Прогониста форма і досить тонка п`ята сприяють хорошій аеродинаміці і тому, що цей віброхвіст буде заводитися на найлегших вагах, що важливо при лові на мілководді або в умовах запресованого хижака. Приманка демонструє стабільну гру як на річках з сильною течією, так і на ставках та водосховищах, чудово спокушаючи окуня, щуку, судака та інших напівхижих риб. Крім високих їстівних якостей, цей віброхвіст має гарну стійкість до зубів хижака, що значно продовжує життя приманки. Монтаж з офсетним гачком, одинарним або двійником найкраще поєднуються з E.T.Shad.','https://fishingstock.ua/upload/iblock/57f/57fe2cfdea2ffe5ece894314a725e70c.jpeg, https://fishingstock.ua/upload/iblock/5ca/5cad540272731e8d2662db541af496f2.jpeg','шт.',249.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
