INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2595,'Приманка Bait Breath BeTanCo Curly Tail 2" (8шт.) (S853 Motor Oil/Gold)','FS0634197','Ця оригінальна приманка буває незамінною у прісноводних водоймах, населених бичком. Не секрет, що бички є делікатесом для всіх хижих риб – вони малорухливі, позбавлені гострих колючок, міцно прив''язані до донного ґрунту. У ситуації джигового лову пасивного, малорухливого хижака - імітація бичка може стати головним козирем спінінгіста. А якщо цей штучний бичок ще й такий ароматний, такий смачний, як Bait Breath BeTanCo Curly Tail – ваші шанси на успішну рибалку стають майже стовідсотковими. Анімація - елементарна і нехитра, це рівномірне волочіння по дну, або короткі протяжки без відриву від грунту, з довгими паузами. Клювання найчастіше виявляється у потужному нависанні на джигу - хижак думає, що спіймав смачного бичка, але рибалок точно знає: зубастий сам попався!','https://fishingstock.ua/upload/iblock/8e8/8e8500b560368e7a782b571b7c82f517.jpg','шт.',236.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
