INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2864,'Приманка Bait Breath SL-Remix Chiby SP 2,4" (10 шт) (Ur120 Green Pumpkin/Seed)','FS0634379','Приманка Bait Breath SL-Remix Chiby SP 2,4" (10 шт) - новинка 2019 року, точніше абгрейд старої моделі SL-Remix Chiby. Новинка також є двовостим раком і відрізняється наявністю лапок, що додає жвавості приманці і більш жорстким силіконом тепер більш зносостійкий до клювання хижака, а також розширена лінійка кольорів.','https://fishingstock.ua/upload/iblock/804/804ce1973059f59e8cf93ae5da20fa38.jpg','шт.',234.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
