INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2950,'Волосінь Intech Galaxy Ice Line 50m','','Intech ICE GALAXY - волосінь останнього покоління, призначена для зимового лову. Вона відповідає всім сучасним вимогам рибалок. Має голубуватий відтінок, що робить її помітнішою на льоду, при цьому вона практично не помітна для риби. Матеріал, з якого виготовлена волосінь, має підвищену стійкість до абразиву, не вбирає воду і має хороші амортизуючі властивості. Має високу міцність на вузлах, не втрачає своїх властивостей при негативній температурі і практично не має ефекту пам`яті. Лісочка виробляється в Японії з використанням найякіснішої сировини та новітніх технологій.','https://fishingstock.ua/upload/iblock/cd7/cd75aade096d0207ab2a51bb73cdfa1a.jpeg','шт.',50.0,6,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
