INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (2993,'Леска Intech Galaxy Ice Line 50m (0.236mm, 4.52kg)','FS0634336','Intech ICE GALAXY - волосінь останнього покоління, призначена для зимового лову. Вона відповідає всім сучасним вимогам рибалок. Має голубуватий відтінок, що робить її помітнішою на льоду, при цьому вона практично не помітна для риби. Матеріал, з якого виготовлена волосінь, має підвищену стійкість до абразиву, не вбирає воду і має хороші амортизуючі властивості. Має високу міцність на вузлах, не втрачає своїх властивостей при негативній температурі і практично не має ефекту пам''яті.
