INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3052,'Воблер Raid Level Minnow (125mm, 14g) (011 Clown)','FS0640317','Raid Level Minnow - мінноу класичної форми, який розроблявся як один із найкращих у своєму класі. Його напівкругла форма лопаті дозволяє воблеру нишпорити і розвертатися в горизонтальній площині - це виглядає більш природно і дозволяє тримати обрій, мінімізуючи контакт з придонними зачепами. Воблер має ретельно розроблену магнітну систему, яка переносить центр ваги ближче до хвоста в польоті і повертає його на місце при приводнінні. Текстурована поверхня, живі очі та виразні зябра – всі ці деталі у прозорій воді можуть грати вирішальну роль для атаки хижака. Розробник моделі Такаші Канаморі - найвідоміший у Японії рибалок, зробив оригінальну форму лопаті "Semi-Catapult Lip", яка забезпечує стабільне утримання приманки в горизонті близько півтора метра.','https://fishingstock.ua/upload/iblock/3ba/3ba1f57abdd4e01b8480d824a4a7c343.jpg','шт.',769.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
