INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3084,'Воблер Raid Level Vib Boost (38mm, 7g) (001 Shimanashi Tiger)','FS0640246','Level Vib Boost – другий семиграмовий брат у лінійці вібів компанії Raid. Безперечною перевагою цього віба-цикади є максимальна дальність закидання та активне вібрування на найповільнішому підмотуванні. Він чудово підійде при лові окуня, судака, щуки та жереха з човна та берега. А коли всі приманки замовкли, ви просто зобов''язані закинути і повільно порвести Level Vib Boost - він "заведе" всього хижака довкола до стану, коли він почне шукати, хтось так активно тікає його територією. Проводку можна робити рівномірно-хвилеподібну та ступінчасту.','https://fishingstock.ua/upload/iblock/23c/23c5a2f1dfa124e3088945938528c11f.jpg','шт.',453.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
