INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3099,'Воблер Raid Level Vib Boost (46mm, 9g) (001 Shimanashi Tiger)','FS0640261','Level Vib – третій дев''ятиграмовий брат у лінійці Boost від компанії Raid. Безперечна перевага цього раттліну - максимальна дальність польоту та активна гра на повільній проводці. Він чудово підходить як для берегового, так і для човнового лову окуня, судака, щуки та жереха і коли звичайні приманки замовкають, просто необхідно спробувати Level Vib Boost – він може "завести" всіх хижаків в окрузі до стану, коли вони почнуть шукати, хто так активно рухається з їхньої території. Проведення може бути як рівномірне і хвилеподібне, так і ступінчасте.','https://fishingstock.ua/upload/iblock/a7c/a7c05e66b57554ad129c8a93bdaeda69.jpg','шт.',493.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
