INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3112,'Воблер Raid Level Vib Boost (46mm, 11g) (001 Shimanashi Tiger)','FS0640274','Найважчий із побратимів лінійки Level Vib Boost має вагу 11g і має найвизначніші параметри дальності та точності польоту. Його плеската форма, властива більш простим цикадам, проте не робить його таким же вимогливим до швидкості проводки. На відміну від інших побратимів-вібів, він здатний поставити рекорд дальності чекаючи такої ваги приманки і в той же час дати можливість зробити якісну та повільну проводку. Підібрати оптимальну швидкість дуже просто – треба дивитися на кінчик і коли він почне видавати максимальну амплітуду – це і є максимально ефективність.','https://fishingstock.ua/upload/iblock/4e3/4e342ca289513e2f8dff8f688953dc16.jpg','шт.',493.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
