INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3126,'Воблер Raid Level Shad (50.3mm, 4.3g) (001 Lime Chart)','FS0640324','У компактний Raid Level Shad японські розробники вклали чимало технічних секретів. Завдяки системі далекого закидання він відмінно, як для шада, літає, а через оптимальний нахил і форму лопаті він швидко заглиблюється на свій робочий горизонт. Крім усього іншого Raid Level Shad має досить високий ступінь незачіплюваності завдяки тому, що його лопата "перевалює" тіло через зачіп, захищаючи собою трійники. Воблер володіє високочастотною грою, яка імітує видобуток, що швидко втікає, провокує хижака почати переслідування, тому що в кожному хижаку включається інстинкт взяти участь у полюванні за втікачем.','https://fishingstock.ua/upload/iblock/178/178f5fcb58f6ddd89c1cf41d97bf5fd3.jpg','шт.',651.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
