INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3141,'Воблер Raid Level Shad Sprinter 68SR (68mm, 5.6g) (007 Shirauo)','FS0640339','Високочастотний дрібнозаглиблювальний Level Shad 68SR здатний здивувати самого хижака, що не бере, що затаївся на дні і здавалося б не реагує взагалі ні на що. Однак варто закинути Левел Шад, що відмінно літає, і і ви побачите, на що він здатний. Частота підібрана таким чином, щоб імітувати жертву, що швидко втікає, у якої дуже швидко закінчаться сили. Ця частота ніби каже хижакові: це не звичайна рибка, яка прогулюється (яких тисячі), а саме жертва, яку просто необхідно атакувати якнайшвидше, інакше її наздоженуть інші.','https://fishingstock.ua/upload/iblock/767/767055ccb5a5e4f637777519df037197.jpg','шт.',651.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
