INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3176,'Гачок одинарний Intech Tournament Spear SMV-32SB','','Японський одинарний гачок Intech Tournament Spear SMV-32SB1 розроблений спеціально для наших хижаків та має збільшене вухо для кращої рухливості. Гачок виготовлений на сучасному обладнанні із високоміцної каліброваної сталі. Покриття гачка PTFE - надійно захищає від корозії, а також сприяє покращенню проникаючих властивостей, форма була підібрана таким чином, щоб покращити засікання та утримання трофея. Коване жало гачка підвищує надійність і стійкість заточування. Made in Japan - зроблено на заводі Vanfook. Розміри гачків найкраще підходять для ультралайтового і лайтового лову: гачок #2 - оптимальний вибір для приманок розміром 2.5"-2.8" його довжина становить 29mm, #4 - має довжину 25mm і стане кращим вибором для приманок 2"- 2,5", Гачок #6 довжиною 21mm якнайкраще поєднується з принадами 1,5"-2" дюйма.','https://fishingstock.ua/upload/iblock/a37/a373635f7fd2221d5f36c8eb62959bef.jpeg, https://fishingstock.ua/upload/iblock/e88/e8868e38e9b48213eb1d7f7bf368ecc3.jpeg','шт.','',5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3177,'Крючок одинарный Intech Tournament Spear SMV-32SB (#06 (6шт))','FS0642211','Японський одинарний гачок Intech Tournament Spear SMV-32SB1 розроблений спеціально для наших хижаків та має збільшене вухо для кращої рухливості. Гачок виготовлений на сучасному обладнанні із високоміцної каліброваної сталі. Покриття гачка PTFE - надійно захищає від корозії, а також сприяє покращенню проникаючих властивостей, форма була підібрана таким чином, щоб покращити засікання та утримання трофея. Коване жало гачка підвищує надійність і стійкість заточування. Made in Japan - зроблено на заводі Vanfook. Розміри гачків найкраще підходять для ультралайтового і лайтового лову: гачок #2 - оптимальний вибір для приманок розміром 2.5"-2.8" його довжина становить 29mm, #4 - має довжину 25mm і стане кращим вибором для приманок 2"- 2,5", Гачок #6 довжиною 21mm якнайкраще поєднується з принадами 1,5"-2" дюйма.','https://fishingstock.ua/upload/iblock/d9a/d9ae12ae0322f9f2705c008db908af90.jpg','шт.',60.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
