INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3213,'Воблер Raid Level Shad Sprinter 68SR (68mm, 5.6g) (010 Just Bait)','FS0642351','Високочастотний дрібнозаглиблювальний Level Shad 68SR здатний здивувати самого хижака, що не бере, що затаївся на дні і здавалося б не реагує взагалі ні на що. Однак варто закинути Левел Шад, що відмінно літає, і і ви побачите, на що він здатний. Частота підібрана таким чином, щоб імітувати жертву, що швидко втікає, у якої дуже швидко закінчаться сили. Ця частота ніби каже хижакові: це не звичайна рибка, яка прогулюється (яких тисячі), а саме жертва, яку просто необхідно атакувати якнайшвидше, інакше її наздоженуть інші.','https://fishingstock.ua/upload/iblock/3f1/3f1f01b918a705a571569f8bb10a1aba.jpg','шт.',651.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3214,'Воблер Raid Level Minnow Plus (125mm, 14g) (001 Neon Wakasagi)','FS0642338','Воблер Raid Level Minnow Plus має довжину 125мм та вагу 14г, на робочу глибину він занурює досить швидко, тим самим не втрачаючи частину ефективної фази проводки. Японські розробники усвідомлено заклали в цю модель невеликий позитивний ступінь плавучості, завдяки чому якщо лопать упирається в перешкоду, то досить зробити невелику паузу і він трохи підспливе і можна буде продовжити проводку. Також при відстрілі Level Minnow просто випливе і ви зможете його врятувати. Level Minnow має систему далекого закидання у вигляді куль, що перекочуються в хвіст при закиданні, завдяки чому воблер летить далеко і точно. Але головна особливість моделі – несхожість гри на відомих конкурентів при твічинговій проводці, завдяки чому його можна використовувати, коли інші воблери не спрацювали.','https://fishingstock.ua/upload/iblock/3b1/3b1be67860235821a8e439e5db96798b.jpg','шт.',769.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
