INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3216,'Воблер Raid Level Minnow Plus (125mm, 14g) (004 Real Kinkuro)','FS0642340','Воблер Raid Level Minnow Plus має довжину 125мм та вагу 14г, на робочу глибину він занурює досить швидко, тим самим не втрачаючи частину ефективної фази проводки. Японські розробники усвідомлено заклали в цю модель невеликий позитивний ступінь плавучості, завдяки чому якщо лопать упирається в перешкоду, то досить зробити невелику паузу і він трохи підспливе і можна буде продовжити проводку. Також при відстрілі Level Minnow просто випливе і ви зможете його врятувати. Level Minnow має систему далекого закидання у вигляді куль, що перекочуються в хвіст при закиданні, завдяки чому воблер летить далеко і точно. Але головна особливість моделі – несхожість гри на відомих конкурентів при твічинговій проводці, завдяки чому його можна використовувати, коли інші воблери не спрацювали.','https://fishingstock.ua/upload/iblock/461/46195011444cacb9bbcc8f9ed06a537f.jpg','шт.',769.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
