INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3231,'Шнур плетений Intech Tournament Micro Style PE X4 150m','','Intech Tournament Micro Style – ідеальне втілення інноваційних технологій, японської якості та доступної ціни. Завдяки тісній співпраці компанії Intech з японським виробником вдалося вперше отримати шнур преміального класу, але за значно меншою ціною серед аналогічних пропозицій. Tournament Micro Style дійсно тонкий і є одним із найміцніших у своєму класі. У виробництві використовується прогресивна сировина IZANAS, популярна у виробництві топових лінійок шнурів, що використовуються такими гігантами, як Sunline, YGK, Gosen та ін. буд. Використання мікрокрокової технології плетіння дозволило отримати щільно сплетений шнур, що відрізняється найвищою чутливістю внаслідок низького ступеня розтягування і гладкою структурою, що дозволяє досягти збільшення в дальності закидання, а стійкість до абразиву дозволяє використовувати шнур у найскладніших умовах лову. У мікроджиговому лові до шнура найвищі вимоги, які шнур Tournament Micro Style виправдовує на всі 100%. Широкий розмірний ряд від #0.175 дозволяє з комфортом застосовувати його при ловлі нано джигом, а #0.5 можна сміливо рекомендувати для лайтового делікатного лову пасивного хижака.','https://fishingstock.ua/upload/iblock/4c0/4c09eb4e833e10a244667db6630196c3.jpeg','шт.',568.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
