INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3237,'Воблер Megabite Amigo 110 SP (110 мм, 14,3 гр, 1,0 m) (A_10)','FS0632654','Amigo 110 SP – класичний воблер-мінноу. Прекрасно гнітиться, але має і власну гру (ризання середньої активності з осьовими коливаннями з боку на бік). Відмінно працює на великих площах. Ефективний на всіх варіантах проводки: ривкова, рівномірна і stop&go. У паузах хороший результат приносять акуратне пожвавлення приманки мінімальним посмикуванням вершинки
