INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3251,'Воблер Megabite Balance 72 SP (72 мм, 6,9гр, 1m) (A_6)','FS0632682','Воблер Megabite Balance 72SP - дуже сучасний мінноу, що втілює у своїй конструкції кілька дуже цікавих конструктивних рішень. Тіло приманки має форму тригранної призми, поперечний переріз якого звужується у бік черевця (подібно до культової серії Zip Baits Rigge). При правильному балансуванні подібні мінноу можуть творити на ривковій проводці справжні чудеса - але в концепцію бюджетної приманки дорога магнітна система з вольфрамовим вантажем на напрямному стрижні не вкладається.
