INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3254,'Воблер Megabite Dandy 90 SP (90 мм, 11,4 гр, 1,0 m) (1)','FS0632765','Dandy 90 SP - багатоцільовий, дуже універсальний далекобійний мінноу, ефективний у багатьох ситуаціях. Має власну гру, але чудово працює на твічінгу. Особливість воблера – відносно високе тіло, що забезпечує неповторні, дуже привабливі для хижака поздовжні погойдування корпусу як на ривках, так і під час паузи.
