INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3306,'Воблер Raid Level Vib Boost (38mm, 5g) (007 Chi Gill)','FS0642535','Компактний «vib» Boost має вагу всього 5г, завдяки чому здатний облавлювати мілководдя і вмовляти на клювання найнезговірливіших хижаків. Це може бути і форель, і щука і окунь і, звичайно, судак. Плюсне тіло нагадує цикаду, проте на відміну від неї Level Vib Boost має активну і стабільну гру на найповільніших швидкостях проводки.','https://fishingstock.ua/upload/iblock/f70/f7043ccae61644c03bbc7e236c33d97c.jpg','шт.',453.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
