INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3315,'Виброхвост Raid Full Swing 3.5" (7шт.) (042 Dark Cinnamon Shad)','FS0642558','Їстівний віброхвіст Raid Full Swing 3.5" відрізняється від інших своїх побратимів унікальними характеристиками зносостійкості до зубів хижака. Він зроблений з дуже щільного пластику, який, тим не менш, має достатню пластичність, щоб включати хвостову лопату в гру на мінімальних вагах. форма дає правильну орієнтацію в польоті, за рахунок чого можна розраховувати на велику дальність закидання.Віброхвіст має дуже виразну гру і апетитним розгойдуванням тулуба.','https://fishingstock.ua/upload/iblock/aaa/aaa45fc9db1fa819663bdf84029e355b.jpg','шт.',274.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
