INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3379,'Застежка Intech Tournament Drop Snap Matt black (9 шт) (#0)','FS0642600','Tournament Drop Snap Black – це оновлення популярної лінійки супер міцних застібок Drop Snap. На численні прохання рибалок, застібка, що полюбилася, тепер виробляється в матовому чорному кольорі, що позитивно позначається на маскування оснастки. На відміну від подібних чорних застібок, де фарба швидко сходить, у застібках Intech застосовується технологія покриття, що утворює прямі зв''язки молекул металу та фарби, що дає однорідне та стійке забарвлення, стійке до зовнішніх впливів. Як і класична версія, застібки Tournament Drop Snap Black відрізняються підвищеною міцністю та надійністю. Широкий розмірний ряд дозволить підібрати застібку для лову як дрібного окуня, так і великої обережної риби, для чого дроп сніп найкраще підходить. Серія Drop Snap – це найкращий вибір для трофейної риболовлі!','','шт.',46.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
