INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3384,'Застежка Intech Quick lock Snap Matt black (9 шт) (#0)','FS0642605','Quick lock Snap Black - класична американка, виготовлена з якісного пружинного дроту. Матово - чорний колір застібки добре її маскує в оснащенні - на думку більшості шанувальників фідерного і донного лову не яскравий колір має ключове значення. На відміну від подібних чорних застібок, де фарба швидко сходить, у застібках Intech застосовується технологія покриття, що утворює прямі зв''язки молекул металу та фарби, що дає однорідне та стійке забарвлення, стійке до зовнішніх впливів. Подовжений загин дає низку переваг на монтажі типу Jig-Rig. Відрізняється зручністю використання, доступною ціною та широким розмірним рядом. Застібки Quick lock Snap Black за сукупністю характеристик є відмінним вибором як для любителів, так і для досвідчених рибалок.','','шт.',21.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
