INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3390,'Застежка с вертлюжком Intech Quick lock Snap Rolling Matt black (5 шт) (#0)','FS0642611','Quick lock Snap Rolling Black – класична американка з вертлюгом. Увібрала в себе всі переваги застібки Quick lock Snap Black: звична та зручна форма, матово-чорний колір, висока якість матеріалу та демократична ціна. Застосовується спеціальна технологія покриття, що утворює прямі зв''язки молекул металу і фарби, що дає однорідне і стійке забарвлення, стійке до зовнішніх впливів. Нову застібку гідно оцінять шанувальники лову блешнями, якісний вертлюжок надійно захищає шнур від перекручування, особливо це актуально при лові на блешні, що обертаються. Також темна застібка з вертлюжком є невід''ємною частиною лову фідера та інших проявів донної риболовлі, де можливі перекручування волосіні і застосування вертлюга є обов''язковим.','','шт.',24.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
