INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3396,'Приманка Intech Slim Shad 4 "(5 шт) (#05)','FS0642057','Intech Slim Shad – класичної форми віброхвіст, який став ще одним впевненим кроком наших виробників на шляху створення досконалої приманки. Унікальність властивостей пояснюються простим рішенням – хвостова частина та саме тіло розділене тонкою перегородкою, завдяки якій коливання Slim Shad виходять м''якими, високочастотними, але не надто агресивними.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3397,'Приманка Intech Turborib 3"(7 шт) (#30)','FS0642064','','https://fishingstock.ua/upload/iblock/dfc/dfcf364f90653fe6c930fc069b3be827.jpg','шт.',60.04,2,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3398,'Гачок двійний Intech Tournament Longaff DFV-23SB','','Intech Tournament Longaff DFV-23SB – двійник найвищої якості, спільна розробка українських рибалок зі світовим лідером галузі, японською компанією Vanfook. Поряд з винятковою гостротою та надійністю, характерною особливістю двійника є подовжена цівка та використання більш тонкого, але пружного дроту. Це дозволяє правильно оснащувати приманки від 3" до 5" дюймів, виключаючи образливі сходи та відкуси хвостів. Завдяки особливій хімічній обробці металу, двійники Longaff мало сприйнятливі до корозії і тому забутий двійник у тілі їстівної приманки тривалий час зберігає виняткову гостроту та зовнішній вигляд.','https://fishingstock.ua/upload/iblock/0b8/0b8a9fa074446346a81e298e5dd70f26.jpeg','шт.',102.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
