INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3514,'Воблер Madness Shiriten VIBE 53 (53mm, 8,5gr)','','Воблери Madness Vibe Найбільш вдала модель даного виду приманок, і є кілька типорозмірів цього сімейства, для задоволення широкого кола завдань при лові ними. Особливість цих приманок дозволяє використовувати їх як в теплий період, так і взимку. Обтічна форма сприяє пробиванню повітряних потоків, що збільшить дальність закидання. Здатність ефективно грати, при занурення на глибину, стане в нагоді як на лові з човна, крутого берега, так і при занурення під лід. Наявність цікавих забарвлень і висока якість виконання забарвлення допоможе у досягненні результатів.
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3515,'Воблер Madness Shiriten VIBE 53 Tungsten (53mm, 12gr)','','','https://fishingstock.ua/upload/iblock/2cc/2cc9521a1a5ed4a10459a8151dfc560f.jpeg, https://fishingstock.ua/upload/iblock/217/2177937332abf3ad7c01f7f996d55a7f.jpeg','шт.',959.0,2,226,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3516,'Воблер Madness Shiriten VIBE 73 (73mm, 17gr)','','','https://fishingstock.ua/upload/iblock/0f7/0f74ec875eb0c596cac96530f9786b20.jpeg, https://fishingstock.ua/upload/iblock/e5b/e5bc932f0a708a35b443701861690ebf.jpeg','шт.',883.0,2,226,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3517,'Воблер Madness Shiriten VIBE 53 (53mm, 8,5gr) (#02)','FS0649284','<p><strong>Воблери Madness Vibe</strong> Найбільш вдала модель даного виду приманок, і є кілька типорозмірів цього сімейства, для задоволення широкого кола завдань при лові ними. Особливість цих приманок дозволяє використовувати їх як в теплий період, так і взимку. Обтічна форма сприяє пробиванню повітряних потоків, що збільшить дальність закидання. Здатність ефективно грати, при занурення на глибину, стане в нагоді як на лові з човна, крутого берега, так і при занурення під лід. Наявність цікавих забарвлень і висока якість виконання забарвлення допоможе у досягненні результатів.<br /><br />Той факт, що приманки цієї молодої фірми дісталися України, свідчить про їх достатній рівень якості, щоб представляти і не осоромити репутацію своєї країни, як світового лідера з виробництва рибальських приманок. Навіть якщо просто брати зовнішній вигляд воблерів, то відчувається прихильність їх до рівня більш іменитих конкурентів. Спробуйте наявність всесезонної моделі від виробника з Японії ніколи не буде зайвою, особливо якщо потрібно розширити свій арсенал представниками цього класу.</p>','https://fishingstock.ua/upload/iblock/ad7/ad76e3e042c61166481e9d096a8aff67.png','шт.',808.0,2,226,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
