INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3566,'Мормишка Intech Ice Jig Олівка з петелькою ?2.0*6.0 (10шт)','','Мормышка Intech Ice Jig - предназначена для подледной ловли. Данный тип приманки зарекомендовал себя как самый уловистый для всех видов рыб. Чем уникальна мормышка Intech Ice Jig: • Надежный крючок. Мормышки оснащены японским крючком Hayabusa. • Уникальная технология прессовки. Мормышки Intech Ice Jig изготовлены по уникальной технологии прессовки, которая позволяет получить вольфрам высокой плотности. Удельный вес вольфрама в такой мормышке практически не отличается от точеного; • Щадящая пайка. Пайка крючка к телу мормышки происходит при сравнительно малых температурах, что позволяет сохранить все пружинящие свойства крючка (крючок не разгибается) и долговечность его покрытия. • Популярные модели. Отобраны самые интересные модели, которые популярны среди спортсменов и почитателей зимней рыбалки.','https://fishingstock.ua/upload/iblock/8f7/8f7e31ebed6c7be73e74ec1d9595bc83.jpeg','шт.','',6,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
