INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3599,'Приманка Bait Breath Skeleton Shrimp SSP (8шт.) (#135 Cola Color)','FS0634013','Skeleton Shrimp SSP - фантазійна приманка, що імітує ракоподібне. Рухливі ніжки приманки активно вібрують під час проведення. Приманка не вимоглива до ваги завантаження та типу монтажу. Класична шарнірна сполука, кароліна або техас на повну розкриє потенціал приманки. 2.7 дюйма універсальний розмір, що дозволяє полювати на окуня, щуку та судака цілеспрямовано.
