INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3611,'Флюорокарбон Intech First FC 8м (0.30mm (6.22kg / 13.7lb))','FS0649334','Intech First FC – флюорокарбон новинка 2021 року, який своєю появою на ринку встановив новий, вищий стандарт якості у сегменті доступних шок-лідерів для рибалок у складних та навіть екстремальних умовах. Серія First розроблена спеціально для використання як зносостійкий повідець у спінінговому та фідерному лові. Лінійка розмірів включає 7 діаметрів від 0.30 мм до 0.60 мм і повністю задовольняє потребам сучасного спінінгіста. Відмінною рисою флюорокарбону First є його м''якість, це дозволяє подати приманку більш природно, не сковуючи її рухів. Застосування такого повідця особливо актуальне з використанням різноманітних блешень і воблерів, де важливий кожен елемент анімації, особливо, якщо йдеться про пасивний хижак і точкові анімації. Intech First FC відмінно підходить для лову фідера як повідець при лові в максимально складних умовах. Даний флюорокарбон має високі показники абразивостійкості в черепашці, корчах, на прямовисних брівках, завдяки чому при правильному поводженні зі снастю допоможе впевнено доставити трофей будь-яких габаритів у руки рибалці.','https://fishingstock.ua/upload/iblock/775/775a58a8305a57e87733f24548ade148.jpg','шт.',44.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
