INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3707,'Шнур плетеный Intech First Braid X4 Green 100m (0.3 (6lb/2.72kg))','FS0649446','Intech First PE X4 - універсальний сучасний шнур, який має встановити новий високий стандарт якості в бюджетному сегменті рибальських шнурів. Має широку розмірну лінійку і дозволяє легко укомплектувати будь-яку снасть, від легкого ультралайту до потужної важкої снасті, орієнтованої на трофейний лов. Виготовляється за сучасними технологіями з високоякісного поліетилену, має щільне та однорідне плетіння та мінімальний ступінь розтягування. Володіє високими показниками міцності і стійкістю до абразиву, тому шнур ідеальний для складних умов лову. Шнур не вибагливий до вузлів і не втрачає своїх показників тривалий час. Випускається у двох розмотках 100м та 150м. За сукупністю характеристик шнур First PE X4 можна рекомендувати як новачкам, так і досвідченим рибалкам. Шнур невибагливий і довговічний, довів свої високі робочі характеристики на будь-яких котушках і способах лову, він відмінно підійде для спінінга та лову білої риби, де виправдано використання плетеного шнура.','https://fishingstock.ua/upload/iblock/5f0/5f0a14dde87df1880fb8a1d584fde36a.jpeg','шт.',198.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
