INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3751,'Шнур плетеный Intech First Braid X8 Orange 100m (0.6 (12lb/5.45kg))','FS0649465','Intech First PE X8 – це нове покоління бюджетних восьмижильних шнурів. Широкий розмірний ряд, крім звичних товстих і міцних діаметрів #2.0 і #2.5, включає раніше недоступні в цьому ціновому сегменті тонкі діаметри шнура (#0.4), що виводять берегову лайтову рибалку на новий рівень. Шнур має ідеально круглий переріз, надзвичайно слизьке покриття та збільшене розривне навантаження. Intech First PE X8 відкриває для рибалки нові можливості у чутливості, дальності закидання та міцності. У сукупності з доступною ціною First PE X8 безумовно сподобається багатьом шанувальникам джигового, воблерного лову або полювання на дальньому рубежі за обережною рибою, такий, як жерех. Шнур абсолютно нерозтяжний, має високу стійкість до стирання і відмінно підійде для сучасного спіннгового лову у всіх його проявах. Забарвлений у яскравий контрастний колір, випускається у розмотках 100 та 150 метрів.','https://fishingstock.ua/upload/iblock/c14/c14511512952175bffb6da11aa2e5c51.jpeg','шт.',325.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
