INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3781,'Воблер Megabite LB VIB 75 FS Fast Sinking (75 mm, 28 g, 10 m)','','Megabite LB VIB 75S - раттлін, який має вагу 21г і чудово підходить для більшості водойм із чистим дном. Якщо глибина лову менше трьох метрів, то він чудово працюватиме на рівномірній проводці. Якщо глибини в місці лову великі, то ловити потрібно простою сходинкою: два обороти ручки котушки - пауза. Довжина 7,5см є оптимальною для щуки та судака. Має відмінні польотні характеристики. На падінні похитує боками, тому клювання на падінні - не рідкість.','https://fishingstock.ua/upload/iblock/86e/86ed998b271fe62ba6c80f16d579d02a.jpeg','шт.',282.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
