INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3790,'Шнур плетеный Intech First Braid X8 Green 100m (0.4 (10lb/4.54kg))','FS0642649','Intech First PE X8 – це нове покоління бюджетних восьмижильних шнурів. Широкий розмірний ряд, крім звичних товстих і міцних діаметрів #2.0 і #2.5, включає раніше недоступні в цьому ціновому сегменті тонкі діаметри шнура (#0.4), що виводять берегову лайтову рибалку на новий рівень. Шнур має ідеально круглий переріз, надзвичайно слизьке покриття та збільшене розривне навантаження. Intech First PE X8 відкриває для рибалки нові можливості у чутливості, дальності закидання та міцності. У сукупності з доступною ціною First PE X8 безумовно сподобається багатьом шанувальникам джигового, воблерного лову або полювання на дальньому рубежі за обережною рибою, такий, як жерех. Шнур абсолютно нерозтяжний, має високу стійкість до стирання і відмінно підійде для сучасного спіннгового лову у всіх його проявах. Забарвлений у яскравий контрастний колір, випускається у розмотках 100 та 150 метрів.','https://fishingstock.ua/upload/iblock/6c7/6c72372d2236988111f58f9d5f730e14.jpeg','шт.',393.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
