INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3794,'Воблер Megabite Extream VIB 55 S (55 mm, 6 g, 4 m) (21)','FS0642803','Лінійка воблерів Megabite поповнена новим видом приманок – невеликим раттліном. Ця сильно вібруюча приманка з огляду на обтічну форму і відсутність лопаті має відмінні польотні характеристики. Також через яскраво виражену вібрацію раттлін Мегабайт приваблює хижака з великої відстані. Слід пам''ятати. що цей тип приманок необхідно застосовувати в досить чистих місцях з огляду на те, що раттліни (за рідкісним винятком) є тонучими і будучи оснащеними двома трійниками знизу, зберуть все сміття з дна, або зовсім знайдуть глухий зачіп значно швидше, ніж звичайні воблери з нейтральною або позитивною. плавучістю. Дані габарити добре ловитимуть рибу дрібних і середніх розмірів. Основними об''єктами полювання слід вибирати такі види риб, як окунь, судак, щука та жерех.','https://fishingstock.ua/upload/iblock/8bc/8bcee62b4bd7041dfd2889bcbd9527dd.jpg','шт.',289.0,2,120,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
