INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3811,'Разборной груз Intech Tungsten 74 Steel Gray (0.5g (5шт))','FS0649875','При розробці вольфрамових вантажів Intech завдання ставилося просто: зробити найкращий з існуючих розбірних «ушастиків». При великій схожості вантажів різних виробників, вони мають масу відмінностей у формі, покритті, жорсткості та конфігурації дротяної арматури. У вантажі Intech все це оптимізовано з урахуванням багаторічного досвіду експлуатації вольфраму, сотень рибалок, десятків турнірів зі спортивного спінінгу.
