INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3828,'Шнур плетений Intech MicroN Plus PE X4 100m','','Intech MicroN PLUS PE X4 - був ретельно підібраний для асортименту бренду Intech, тестування та відбір проходив понад півроку за низкою фундаментальних властивостей. Головним критерієм відбору була висока якість продукту, на рівні японських шнурів, і максимальна відповідність цього шнура для застосування його у важкому джизі, лові на великі воблери та середні та великі ваги. Можна з упевненістю сказати, що це завдання виконано блискуче: після тестування на стирання, відповідність заявленому діаметру і показників міцності, Intech MicroN PLUS показав найвищі результати за всіма параметрами. У виробництві шнура використовується первинна сировина, що дає незмінно високу і найголовнішу стабільну якість готового продукту. Дана плетенка для риболовлі - одна з найтехнологічніших і найвигідніших пропозицій на ринку в бюджетному сегменті. Шнур має розмотування 150 і 100 метрів і підходить для лову потрійної риби. Таким чином шнур MicroN PLUS є логічним продовженням лінійки шнурів MicroN, а гладка та однорідна структура шнура зберігає дальність закидання та чутливість шнура MicroN. Стійкість кольору до вимивання обумовлена не фарбуванням, як на багатьох бюджетних шнурах, а спеціальним просоченням з додаванням яскравого флюоресцентного пігменту рожевого кольору, це не тільки дозволило отримати стійкий колір, а й покращити стійкість до абразиву.','https://fishingstock.ua/upload/iblock/e1f/e1f74f6cccd4b839c6a4f27f86f83e8e.jpeg, https://fishingstock.ua/upload/iblock/32c/32c5cbea5fbe61189db308cd5d6e7a7a.jpeg','шт.',190.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
