INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3848,'Блешня Yarie Pirica More №702 24mm 1,5g','','Блешня Yarie Pirica More - невелика легка блешня для лову форелі. Блешні Yarie були спеціально розроблені для участі у змаганнях та турнірах. Yarie Jespa Pirica More максимально ефективно працює на повільній проводці. Завдяки продуманій формі на паузі вона не падає каменем, а пурхає, демонструючи хаотичність рухів. При проведенні такої блешні будуть доречні паузи з віддачею шнура. На протязі вона показує стабільну гру, не збивається та не штопорить. Блешня Yarie Jespa Pirica More випускається у двох розмірах по два вагові рішення. Відмінна універсальна приманка, що підходить для лову безлічі хижих риб.','https://fishingstock.ua/upload/iblock/137/137ad323ba7dd1eb7f823c093f43e839.jpeg','шт.','',2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
