INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3850,'Блешня Yarie T-Spoon №706 21mm 1,4g','','Yarie T-Spoon - блешні, спеціально розроблені для лову ставкової форелі. Ці невеликі приманки мають чудові польотні характеристики. Ретельно розроблена форма дозволяє однаково ефективно використовувати будь-які швидкості проводки, завдяки чому цю модель блешні можна вважати універсальною на area-водоймах по форелі будь-яких розмірів. Yarie T-Spoon також найкраще зарекомендувала себе при лові наших хижаків - голавля, язя, жереха. В асортименті даної моделі представлена широка гамма кольорів для задоволення будь-якого настрою форелі.','https://fishingstock.ua/upload/iblock/ff3/ff38a4ba7ed9d83a094bc7de35d21b58.jpeg','шт.','',2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3851,'Блесна Yarie Pirica More №702 29mm 2,2g (BS-2)','FS0650402','Блешня Yarie Jespa Pirica More – невелика легка блешня для лову форелі. Ці блешні були спеціально розроблені для участі у змаганнях та турнірах. Максимально ефективно працює на повільній проводці. Завдяки продуманій формі на паузі вона не падає каменем, а пурхає, демонструючи хаотичність рухів. При проведенні такої блешні будуть доречні паузи з віддачею шнура. На протязі вона показує стабільну гру, не збивається та не штопорить. Блешня випускається в одному розмірі, але з різною вагою. Відмінна універсальна приманка, що підходить для лову безлічі риб.','https://fishingstock.ua/upload/iblock/f21/f21d6b3b8dbca2417fbae98019af19af.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
