INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3891,'Блесна Yarie Ringo №704 28mm 2,1g (BS-3)','FS0650488','Блешня Yarie Jespa Ringo - неймовірно уловиста блешня, має мінімальну підйомну силу на проводці і відмінно тримає заданий горизонт. Особливість геометрії забезпечує свої активну гру навіть на найповільнішій проводці, щоб спокусити максимально пасивну рибу. Кращі результати Yarie Jespa Ringo показує у лові форелі у стоячих водоймах у area-лові. Але також може бути використана і для лову голавля, окуня або жереха на малих та середніх річках. Широка палітра кольорів дозволить вибрати приманку на будь-який смак та під найрізноманітніші умови лову.','https://fishingstock.ua/upload/iblock/545/545c7f851ced7da0c227ffe43514e522.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
