INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (3980,'Блесна Yarie T-Surface №709 25mm 1.2g (AD1)','FS0650597','Yarie Jespa T-Surface - блешня, спеціально розроблена для підповерхневого лову форелі. Робочий горизонт цієї блешні - лов форелі на глибині до 20 см. Принада має велике тіло і рухливу гру, що чудово приваблює хижака і провокує пасивну форель на клювання. За такої малої ваги, блешня Yarie Jespa T-Surface №709 демонструє відмінну дальність закидання, не збиваючись і не змінюючи положення в польоті. Коли форель активно годується біля поверхні - ця приманка здатна стати кращою у коробці та вивести у переможці.','https://fishingstock.ua/upload/iblock/1b7/1b726a645a19f2ef06fcbfb597b94119.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
