INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4083,'Блесна Yarie Pirica More №702 24mm 1,5g (BB-1)','FS0650442','Блешня Yarie Pirica More - невелика легка блешня для лову форелі. Блешні Yarie були спеціально розроблені для участі у змаганнях та турнірах. Yarie Jespa Pirica More максимально ефективно працює на повільній проводці. Завдяки продуманій формі на паузі вона не падає каменем, а пурхає, демонструючи хаотичність рухів. При проведенні такої блешні будуть доречні паузи з віддачею шнура. На протязі вона показує стабільну гру, не збивається та не штопорить. Блешня Yarie Jespa Pirica More випускається у двох розмірах по два вагові рішення. Відмінна універсальна приманка, що підходить для лову безлічі хижих риб.','https://fishingstock.ua/upload/iblock/68a/68a4136e92bb0482a016f679d7087f62.jpg','шт.',186.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
