INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4109,'Блесна Yarie Pirica More №702 24mm 1,8g (V10)','FS0650464','Блешня Yarie Pirica More - невелика легка блешня для лову форелі. Блешні Yarie були спеціально розроблені для участі у змаганнях та турнірах. Yarie Jespa Pirica More максимально ефективно працює на повільній проводці. Завдяки продуманій формі на паузі вона не падає каменем, а пурхає, демонструючи хаотичність рухів. При проведенні такої блешні будуть доречні паузи з віддачею шнура. На протязі вона показує стабільну гру, не збивається та не штопорить. Блешня Yarie Jespa Pirica More випускається у двох розмірах по два вагові рішення. Відмінна універсальна приманка, що підходить для лову безлічі хижих риб.','https://fishingstock.ua/upload/iblock/33f/33f90cf53fcba9bdf4dcc876b8cd37c6.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
