INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4133,'Блесна Yarie T-Spoon №706 21mm 1,4g (BJ-13)','FS0650519','Yarie T-Spoon - блешні, спеціально розроблені для лову ставкової форелі. Ці невеликі приманки мають чудові польотні характеристики. Ретельно розроблена форма дозволяє однаково ефективно використовувати будь-які швидкості проводки, завдяки чому цю модель блешні можна вважати універсальною на area-водоймах по форелі будь-яких розмірів. Yarie T-Spoon також найкраще зарекомендувала себе при лові наших хижаків - голавля, язя, жереха. В асортименті даної моделі представлена широка гамма кольорів для задоволення будь-якого настрою форелі.','https://fishingstock.ua/upload/iblock/3f5/3f5ac7a3a4b0b738669069ab638ca085.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
