INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4153,'Блесна Yarie T-Fresh EVO №710 24mm 1.5g (BJ-13)','FS0650619','Yarie T-Fresh EVO - новинка в лінійці блешень, що коливаються, розроблених для лову ставкової форелі від японської компанії Yarie. Дана блешня призначена для лову в середніх шарах активної та середньоактивної форелі. Ця блешня рекомендується для новачків, так як вона стабільно грає на будь-яких швидкостях проводки і має чудові польотні якості. У той же час, і рибалки з великим досвідом також знайдуть місце застосування цієї блешні, так як при проводках з підривами або збоями в грі вона також швидко повертається до своїх вагань і тим самим заводить і спокушає рибу на атаку. Блешня Yarie T-Fresh EVO №710 чудово зарекомендувала себе при лові наших хижаків, таких як форель, окунь, голавль та жерех.','https://fishingstock.ua/upload/iblock/964/96436aef64467ef70fb96146aa041248.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
