INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4198,'Блесна Yarie Dexter №712 32mm 2.5g (AD20)','FS0650664','Yarie Dexter – новинка від японської компанії Yarie. Ці блешні використовують всі переваги краплевидної форми і грамотне балансування при досить великій вазі. Амплітудні широкі коливання приваблюють форель з максимально великої відстані, блешня чудово працює по активній рибі, збираючи її з далекої відстані. На найповільніших швидкостях блешня Yarie Dexter №712, переходячи в вертикальніше положення, починає купувати гру з наявністю ролінгу, і ловить пасивнішу форель. Yarie Dexter №712 - це та сама блешня, яка спокушатиме рибу будь-якої активності починаючи з дна, і закінчуючи середніми шарами.','https://fishingstock.ua/upload/iblock/6fa/6fa2789c88e7f58e2c7341d396ed30b8.jpg','шт.',208.0,2,208,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
