INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4253,'Розбірний груз Intech Tungsten 74 Gloss Pink UV','','Вольфрамові вантажі Intech – найкращі з існуючих розбірних «вушастиків». При великій схожості вантажів різних виробників, чебурашки Intech Tungsten мають масу відмінностей у формі, покритті, жорсткості та конфігурації дротяної арматури. У вантажі Intech все це оптимізовано з урахуванням багаторічного досвіду експлуатації вольфраму, сотень рибалок, десятків турнірів зі спортивного спінінгу. Форма вантажу – ідеальна куля. Тільки такий вольфрам має найкращу аеродинаміку, він летить далі і точніше за вантаж такої ж маси, але сплюснутого з боків. Вольфрам Intech випускається в широкому діапазоні розмірів і кольорів для лову в каламутній воді, для помітності монтажу на великій глибині (при лові судака) - від мікроскопічних головок масою один і півтора грама, до важких куль тридцятиграмів, що відлітають буквально за горизонт.','https://fishingstock.ua/upload/iblock/c0f/c0f3c8788ce72be75d80416e5268e3fe.jpeg','шт.',81.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
