INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4299,'Гачок офсетний Intech Tournament JIG-RIG Offset WMV-32SB','','Японський гачок офсетний Intech Tournament Jig-Rig Offset WMV-32SB розроблений спеціально для прісноводних і морських хижаків, має збільшене вухо для кращої рухливості на всіляких монтажах, зокрема джиг-риг. Вушко гачка зроблено таким чином, щоб монтаж був максимально рухомий без сторонніх використання елементів монтажу, зокрема заводних кілець. Форма гачка спеціально розроблена нашими експертами і найкраще підходить для використання як прогінних, так і об`ємних варіацій силіконових приманок. Гачок виготовлений на сучасному обладнанні із високоміцної каліброваної сталі. Покриття гачка PTFE – надійно захищає від корозії, гачок максимально придатний для лову прісноводного та морського хижака, не іржавіє у їстівних силіконових приманках. Дане покриття сприяє поліпшенню проникаючих властивостей в пащу риби, а форма була підібрана таким чином, щоб поліпшити засікання та утримання трофея на гачку. Коване жало Forged Barb гачка підвищує надійність і стійкість заточування, гачок залишається гострим навіть після безлічі клювань хижака. Made in Japan – вироблено на заводі Vanfook. Розміри гачків найкраще підходять для ультралайтового і лайтового лову. Гачок #2 - має довжину 37 mm, оптимальний вибір для приманок розміром 3 дюйми. Гачок #4 має довжину 33 мм і стане кращим вибором для приманок розміром до 2,5-2.8 дюйма. Гачок #6 має довжину 31 мм і відмінно підійде для приманок до 2.2-2.5 дюйми. Гачок #8 довжиною 24 мм найкраще поєднується з принадами 1.5-2 дюйми.','https://fishingstock.ua/upload/iblock/98d/98d57c6e437643acbe1dec44b3554269.jpeg, https://fishingstock.ua/upload/iblock/471/471d29b284dc7843221ee0cb2fb3a447.jpeg','шт.',81.0,5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
