INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4369,'Застежка Intech Micro Custom Snap (10 шт)','','Micro Custom Snap – эти застежки порадуют любителей ультралайтовой ловли, так как выполнены они в самых минимальных размерах, возможных на сегодняшний день. Каждая застежка Micro Custom изготавливается вручную.','','шт.','',5,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
