INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4376,'Воблер Yarie T-Crankup Jr. F №675 (28mm, 1.8g)','','Yarie - еталонна японська компанія, виробник воблерів та блешень для лову форелі, який завоював визнання рибалок всього світу на міжнародній арені. Під девізом «Завжди вперед» компанія Yarie прагне бути виробником, який розробляє та пропонує продукти, що відповідають вимогам сучасних спінінгістів.
