INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4426,'Приманка Bait Breath Moebi 3" (10шт.) (106)','','Moebi – приманка, що імітує невеликий кальмар. І хоча в наших водоймах цих істот не зустрінеш, Moebi чудово себе зарекомендував при лові прісноводних хижаків європейської середньої смуги: щуки, окуня, судака. Її "щупальця" - довгі, тонкі, роздвоєні - плавно коливаються навіть за мінімальної швидкості проводки. Бічні ж «плавнички» корисні подвійно. Вони не тільки збільшують час падіння на дно силіконового кальмару (що дозволяє використовувати важчі ваги джиг-головок), але й сприяють хаотичним відхиленням джиги від вертикалі її падіння, створюючи надзвичайно корисний ефект "власного життя" приманки. Moebi чудово працює на досить різнопланових проводках: як на короткій, спокійній і плавній сходинці, так і на різких підривах, запропонованих класичними складами.','','шт.',239.0,2,10,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
