INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4433,'Воблер Raid Level Vib B.I.G. (64mm, 18g) (LVL021. LEMON POWER)','FS0652031','Level Vib Big – найважча версія для великого хижака. Даний раттлін здивує будь-якого рибалки своєю дальністю польоту та стабільною грою на будь-якій швидкості проводки. Враховуючи вагу та габарити, Level Vib Big здатний розворушити хижака та змусити атакувати з дуже великої відстані. Саме тому просунуті рибалки дістають його з коробки, коли в місці лову точно присутній великий судак, щука або пелагічний жерех або коли лов ведеться з берега і потрібно будь-що докинути до крапки і здивувати велику рибу на платнику. Проводити його можна і сходинкою та рівноміром, головне - підібрати швидкість, при якій раттлін вібруватиме найбільш амплітудно.','','шт.',690.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
