INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4455,'Воблер Raid Level Crank Goriller (66mm, 17.5g) (003. NEON BACK CHART)','FS0652012','Воблер Raid Level Crank Goriller довжиною 6,6 см має вагу 17,5 г і може називатися одним з найактивніших кренків. Габарити кренк має досить об''ємні, проте при закиданні завдяки ретельно підібраній формі, що обтікає, він орієнтується строго вздовж осі польоту, не обертається і його можна назвати відмінним літуном. Крім усього іншого, Level Crank Goriller має досить тонку, але міцну квадратну лопату, яка не заважає йому літати, але забезпечує дуже активне розгойдування з боку в бік на рівномірній проводці і відмінну прохідність по траві, захищаючи трійники від нависання сміття. Насамперед його можна назвати вбивцею великих щук на поливах з рідкісною рослинністю, однак і голавль і навіть жерех товарного розміру не пропустить цього товстуна повз себе.','','шт.',690.0,2,150,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
