INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4512,'Шнур плетений Intech MicroN PE X4 150m (0.15 (4.4lb/2.0kg))','FS0652167','ШНУР ПЛЕТЕНИЙ INTECH MICRON PE X4 150M був ретельно підібраний для асортименту бренду Intech з безлічі варіантів. Головними критеріями відбору були якість лише на рівні японських шнурів і ціна, як і китайських. Можна з упевненістю сказати, що це завдання виконано блискуче: після тестування на стирання, відповідність заявленому діаметру і показників міцності, Micron показав найвищі результати за всіма параметрами. Ця пелетенка - одна з найвигідніших пропозицій на ринку за співвідношенням ціна-якість. Шнур має розмотування 150 метрів, що дозволить зберегти робочу ділянку навіть у разі кількох обривів внаслідок петель, що утворюються.','https://fishingstock.ua/upload/iblock/a6a/a6ad0793269d6c791ee649a430563a5a.jpeg','шт.',418.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');
INSERT INTO "products" ("id","name","sku","description","imageUrl","unit","price","categoryId","brandId","createdAt","updatedAt") VALUES (4513,'Шнур плетений Intech MicroN PE X4 100m (0.15 (4.4lb/2.0kg))','FS0652167','ШНУР ПЛЕТЕНИЙ INTECH MICRON PE X4 150M був ретельно підібраний для асортименту бренду Intech з безлічі варіантів. Головними критеріями відбору були якість лише на рівні японських шнурів і ціна, як і китайських. Можна з упевненістю сказати, що це завдання виконано блискуче: після тестування на стирання, відповідність заявленому діаметру і показників міцності, Micron показав найвищі результати за всіма параметрами. Ця пелетенка - одна з найвигідніших пропозицій на ринку за співвідношенням ціна-якість. Шнур має розмотування 100 метрів, що дозволяє заощадити гроші і взяти даний товар на пробу для підбору під лов своїми вагами.','https://fishingstock.ua/upload/iblock/c1b/c1bb5d28b76f3c6d6c0a49e9d434fcda.jpeg','шт.',287.0,3,90,'2025-09-18 14:22:59.339 +00:00','2025-09-18 14:22:59.339 +00:00');